\begin{prob}
બતાવો કે જો કોઈ !!{injective} વિધેય $g\colon B \to A$ હોય અને
$B$ એ !!{nonenumerable} હોય, તો $A$ પણ અગણનીય છે.
$A$ની પરિગણનામાંથી $B$ની પરિગણના બનાવવા $g$નો ઉપયોગ કેવી રીતે
કરી શકાય તે બતાવીને આ કરો.
\end{prob}

\begin{prob}
ન્યૂનીકરણની દલીલ વડે બતાવો કે ધન પૂર્ણાંકોની જોડોના બધા
\emph{ગણોનો} ગણ !!{nonenumerable} છે.
\end{prob}

\begin{prob}\label{sfr:siz:red:prob:nat-nat}
  ન્યૂનીકરણની દલીલ વડે બતાવો કે બધા વિધેયો
  $f\colon \Nat \to \Nat$નો ગણ~$X$ !!{nonenumerable} છે.
  (સંકેત: $X$થી $\Bin^\omega$માં વ્યાપ્ત વિધેય આપો.)
\end{prob}

\begin{prob}
ન્યૂનીકરણની દલીલ વડે બતાવો કે પ્રાકૃતિક સંખ્યાઓના અનંત
અનુક્રમોનો ગણ~$\Nat^\omega$ !!{nonenumerable} છે.
\end{prob}

\begin{prob}
$P$ એ ધન પૂર્ણાંકોના ગણથી ગણ~$\{0\}$માંના વિધેયોનો ગણ અને
$Q$ એ ધન પૂર્ણાંકોના ગણથી ગણ~$\{0\}$માંના \emph{આંશિક}
વિધેયોનો ગણ હોય. બતાવો કે $P$ એ !!{enumerable} છે અને $Q$ નથી.
(સંકેત: $\Bin^\omega$ને પરિગણિત કરવાની સમસ્યાનું $Q$ને
પરિગણિત કરવાની સમસ્યામાં ન્યૂનીકરણ કરો.)
\end{prob}

\begin{prob}
$S$ એ ધન પૂર્ણાંકોના ગણથી ગણ \{0,1\}માંના બધા
!!{surjective} વિધેયોનો ગણ હોય; એટલે કે $S$માં બધા
!!{surjective}~$f\colon \PosInt \to \Bin$ છે. બતાવો કે $S$ એ
!!{nonenumerable} છે.
\end{prob}

\begin{prob}
બતાવો કે બધી વાસ્તવિક સંખ્યાઓનો ગણ~$\Real$ !!{nonenumerable} છે.
\end{prob}

ઘણી વાર આપણને એવા વિધેયોના ખાસ કિસ્સાઓમાં રસ હોય છે
જેનાં મૂલ્યો હા/ના પ્રશ્નોના જવાબ આપે છે. ઉદાહરણ તરીકે,
``$n$ અવિભાજ્ય સંખ્યા છે?'' એ પ્રશ્નની સાથે નીચેનું વિધેય જોડાય છે:
\[
\fn{isprime}(n) = \begin{cases}
  1 & \text{જો $n$ અવિભાજ્ય હોય}\\
  0 & \text{અન્યથા.}
  \end{cases}
\]
સંબંધિત $1/0$-મૂલ્યવાળું વિધેય અસરકારક રીતે સંગણનીય હોય,
તો આપણે કહીએ કે હા/ના પ્રશ્નનો \emph{અસરકારક રીતે નિર્ણય}
કરી શકાય છે.

source_text:
\begin{thm}
There are functions from $\Nat$ to~$\Nat$ which are not Turing
computable.
\end{thm}

target_text:
\begin{thm}
$\Nat$થી~$\Nat$માં જતાં કેટલાંક વિધેયો ટ્યુરિંગ-સંગણનીય
નથી.
\end{thm}

source_text:
\begin{defn}
If $M$~is the $e$th Turing machine (in our fixed enumeration), we
say that $e$~is an \emph{index} of~$M$. We write $M_e$ for the $e$th
Turing machine.
\end{defn}

target_text:
\begin{defn}
આપણી નક્કી કરેલી પરિગણનામાં $M$ એ $e$મું ટ્યુરિંગ
મશીન હોય, તો $e$ને~$M$નો \emph{સૂચક} કહીએ છીએ.
$e$મા ટ્યુરિંગ મશીન માટે $M_e$ લખીએ છીએ.
\end{defn}

source_text:
\begin{thm}\ollabel{thm:universal-tm} There is a \emph{universal
  Turing machine}~$U$ which, when started on input $\tuple{e,n}$ 
  \begin{enumerate}
    \item halts iff $M_e$ halts on input~$n$, and
    \item if $M_e$ halts with output $m$, so does~$U$.
  \end{enumerate}
  $U$ thus computes the function $f\colon \Nat \times \Nat \pto \Nat$
  given by $f(e,n) = m$ if $M_e$ started on input~$n$ halts with
  output~$m$, and undefined otherwise.
\end{thm}

target_text:
\begin{thm}\ollabel{thm:universal-tm} એવું \emph{સર્વવ્યાપી
  ટ્યુરિંગ મશીન}~$U$ છે કે ઇનપુટ $\tuple{e,n}$ પર શરૂ કરતાં
  \begin{enumerate}
    \item $M_e$ ઇનપુટ~$n$ પર અટકે ત્યારે અને માત્ર ત્યારે જ તે અટકે છે, અને
    \item $M_e$ આઉટપુટ $m$ સાથે અટકે, તો~$U$ પણ તેમ જ અટકે છે.
  \end{enumerate}
  આમ, $U$ એ $f\colon \Nat \times \Nat \pto \Nat$ વિધેય
  ગણે છે: $M_e$ ઇનપુટ~$n$ પર શરૂ કરીને આઉટપુટ~$m$
  સાથે અટકે ત્યારે $f(e,n) = m$, અને અન્યથા તે અવ્યાખ્યાયિત છે.
\end{thm}

source_text:
\begin{defn}[Halting function]
 The \emph{halting function}~$h$ is defined as
\[
h(e,n) =
\begin{cases}
  \text{0} & \text{if machine~$M_e$ does not halt for input $n$} \\
  \text{1} & \text{if machine~$M_e$ halts for input $n$}
\end{cases}
\]
\end{defn}

target_text:
\begin{defn}[અટકવાનું વિધેય]
 \emph{અટકવાનું વિધેય}~$h$ આ રીતે વ્યાખ્યાયિત છે:
\[
h(e,n) =
\begin{cases}
  \text{0} & \text{જો મશીન~$M_e$ ઇનપુટ $n$ પર ન અટકે} \\
  \text{1} & \text{જો મશીન~$M_e$ ઇનપુટ $n$ પર અટકે}
\end{cases}
\]
\end{defn}

source_text:
\begin{defn} The function~$s$ is defined as
\[
s(e) =
\begin{cases}
  \text{0} & \text{if machine~$M_e$ does not halt for input $e$} \\
  \text{1} & \text{if machine~$M_e$ halts for input $e$}
\end{cases}
\]
\end{defn}

target_text:
\begin{defn} વિધેય~$s$ આ રીતે વ્યાખ્યાયિત છે:
\[
s(e) =
\begin{cases}
  \text{0} & \text{જો મશીન~$M_e$ ઇનપુટ $e$ પર ન અટકે} \\
  \text{1} & \text{જો મશીન~$M_e$ ઇનપુટ $e$ પર અટકે}
\end{cases}
\]
\end{defn}

source_text:
\begin{lem}
The function~$s$ is not Turing computable.
\end{lem}

target_text:
\begin{lem}
વિધેય~$s$ ટ્યુરિંગ-સંગણનીય નથી.
\end{lem}

source_text:
\begin{prob}
The Three Halting (3-Halt) problem is the problem of giving a decision
procedure to determine whether or not an arbitrarily chosen Turing
Machine halts for an input of three $\TMstroke$'s on an otherwise
blank tape. Prove that the 3-Halt problem is unsolvable.
\end{prob}

\begin{prob}
Show that if the halting problem is solvable for Turing machine and
input pairs $M_e$ and~$n$ where $e \neq n$, then it is also solvable
for the cases where $e = n$.
\end{prob}

target_text:
\begin{prob}
બતાવો કે~$e \neq n$ હોય તેવા ટ્યુરિંગ મશીન અને ઇનપુટ
જોડ $M_e$ તથા~$n$ માટે અટકવાની સમસ્યા ઉકેલી શકાય,
તો $e = n$ હોય તેવા કિસ્સાઓ માટે પણ ઉકેલી શકાય છે.
\end{prob}

source_text:
\begin{prob} Show that the \emph{partial} function~$s'$ is defined as
  \[
  s'(e) =
  \begin{cases}
    \text{1} & \text{if machine~$M_e$ halts for input $e$}\\
    \text{undefined} & \text{if machine~$M_e$ does not halt for input $e$}
  \end{cases}
  \]
  \emph{is} Turing computable.
\end{prob}

target_text:
\begin{prob} બતાવો કે નીચે પ્રમાણે વ્યાખ્યાયિત
  \emph{આંશિક} વિધેય~$s'$ ટ્યુરિંગ-સંગણનીય \emph{છે}:
  \[
  s'(e) =
  \begin{cases}
    \text{1} & \text{જો મશીન~$M_e$ ઇનપુટ $e$ પર અટકે}\\
    \text{અવ્યાખ્યાયિત} & \text{જો મશીન~$M_e$ ઇનપુટ $e$ પર ન અટકે}
  \end{cases}
  \]
\end{prob}

source_text:
\begin{explain}
In order to represent Turing machines and their behavior by !!a{sentence}
of first-order logic, we have to define a suitable language. The
language consists of two parts: !!{predicate}s for describing
configurations of the machine, and expressions for numbering execution
steps (``moments'') and positions on the tape.

\begin{prop}
\ollabel{prop:mlessk}
If $m < k$, then $!T(M, w) \Entails \num{m} < \num{k}$
\end{prop}

target_text:
\begin{prop}
\ollabel{prop:mlessk}
જો $m < k$, તો $!T(M, w) \Entails \num{m} < \num{k}$.
\end{prop}

source_text:
\begin{proof}
Exercise.
\end{proof}

target_text:
\begin{proof}
કસરત.
\end{proof}

source_text:
\begin{prob}
Prove \olref[tur][und][rep]{prop:mlessk}.
(Hint: use induction on $k-m$).
\end{prob}

target_text:
\begin{prob}
\olref[tur][und][rep]{prop:mlessk} સાબિત કરો.
(સૂચન: $k-m$ પર આગમન વાપરો.)
\end{prob}

\begin{defn}
$!C(M, w, n)$ એ નીચેનું !!{sentence} માનો:
\[
\Obj Q_q(\num{m}, \num{n}) \land \Obj S_{\sigma_0}(\num{0}, \num{n})
\land \dots \land \Obj S_{\sigma_k}(\num{k}, \num{n}) \land
\lforall[x][(\num{k} < x \lif \Obj S_\TMblank(x, \num{n}))]
\]
અહીં~$q$, સમય~$n$ પર~$M$ની અવસ્થા છે;
સમય~$n$ પર~$M$ ખાનું~$m$ વાંચે છે;
$0 \le i \le k$ માટે ખાનું~$i$ સમય~$n$ પર
ચિહ્ન~$\sigma_i$ ધરાવે છે;
અને~$k$ એ સમય~$0$ પરની ટેપનું સૌથી જમણું ખાલી
ન હોય એવું ખાનું તથા~$n$ પગલાં પછી હેડે મુલાકાત
લીધેલું સૌથી જમણું ખાનું—આ બેમાંથી વધુ જમણાં
ખાનાનો સૂચક છે.
\end{defn}

source_text:
\begin{lem}\ollabel{lem:halt-config-implies-halt}
If $M$ run on input~$w$ is in a halting configuration after $n$ steps,
then $!C(M, w, n) \Entails !E(M, w)$.
\end{lem}

target_text:
\begin{lem}\ollabel{lem:halt-config-implies-halt}
ઇનપુટ~$w$ પર ચાલતું~$M$,~$n$ પગલાં પછી
અટકવાના સંરૂપણમાં હોય, તો
$!C(M, w, n) \Entails !E(M, w)$.
\end{lem}

source_text:
\begin{explain}
So if $M$ halts for input $w$, then there is some~$n$ such that $!C(M,
w, n) \Entails !E(M,w)$.  We will now show that for any time~$n$,
$!T(M, w) \Entails !C(M, w, n)$.
\end{explain}

target_text:
\begin{explain}
એટલે $M$ ઇનપુટ~$w$ પર અટકે, તો કોઈ~$n$ માટે
$!C(M, w, n) \Entails !E(M,w)$. હવે આપણે
બતાવીશું કે કોઈ પણ સમય~$n$ માટે
$!T(M, w) \Entails !C(M, w, n)$.
\end{explain}

source_text:
\begin{lem}
\ollabel{lem:config}
For each $n$, if $M$ has not halted after $n$ steps, $!T(M, w)
\Entails !C(M, w, n)$.
\end{lem}

target_text:
\begin{lem}
\ollabel{lem:config}
દરેક~$n$ માટે, $M$ જો~$n$ પગલાં પૂરાં થાય તે
પહેલાં અટક્યું ન હોય, તો
$!T(M, w) \Entails !C(M, w, n)$.
\sourcecorrection{OLUN-009}{સ્થિર અંગ્રેજી મૂળનું
``$n$ પગલાં પછી અટક્યું ન હોય'' વિધાન~$n$મા
પગલે જ અટકવાનું સંરૂપણ બાકાત કરે છે, છતાં નીચેનો
પ્રામાણ્યનો પુરાવો એ જ સંરૂપણ માટે આ ઉપપ્રમેય
વાપરે છે. અહીં~$n$ પગલાં પૂરાં થતાં પહેલાં ન
અટકવાની જરૂરી શરત સ્પષ્ટ કરી છે.}
\end{lem}

source_text:
\begin{proof}
Induction basis: If $n = 0$, then the conjuncts of $!C(M, w, 0)$ are
also conjuncts of $!T(M, w)$, so entailed by it.

\item Case \olref{stay} is left as an exercise.
\end{enumerate}
We have shown that for any~$n$, $!T(M, w) \Entails !C(M, w, n)$.
\end{proof}

target_text:
\item \olref{stay} કિસ્સો કસરત તરીકે છોડી છે.
\end{enumerate}
આપણે બતાવ્યું કે આવા દરેક~$n$ માટે
$!T(M, w) \Entails !C(M, w, n)$.
\end{proof}

source_text:
\begin{prob}
Complete case~\olref[tur][und][ver]{stay} of the proof of
\olref[tur][und][ver]{lem:config}.
\end{prob}

target_text:
\begin{prob}
\olref[tur][und][ver]{lem:config}ની સાબિતીમાં
કિસ્સો~\olref[tur][und][ver]{stay} પૂર્ણ કરો.
\end{prob}

source_text:
\begin{lem}
\ollabel{lem:valid-if-halt}
If $M$ halts on input~$w$, then $!T(M, w) \lif
!E(M, w)$ is valid.
\end{lem}

target_text:
\begin{lem}
\ollabel{lem:valid-if-halt}
$M$ ઇનપુટ~$w$ પર અટકે, તો
$!T(M, w) \lif !E(M, w)$ પ્રામાણ્ય ધરાવે છે.
\end{lem}

source_text:
\begin{explain} 
To complete the verification of our claim, we also have to
establish the reverse direction: if $!T(M, w) \lif !E(M, w)$ is valid, then
$M$ does in fact halt when started on input~$w$. 
\end{explain}

target_text:
\begin{explain}
