\begin{defn}
A set of !!{sentence}s~$\Gamma$ is a \emph{theory} if it is closed
under entailment, i.e., if $\Gamma = \Setabs{!A}{\Gamma \Entails
!A}$.
\end{defn}

target_text:
\begin{defn}
!!{sentence}sનો ગણ~$\Gamma$ \emph{સિદ્ધાંત} છે, જો
તે તાર્કિક ફલિતતા હેઠળ બંધ હોય; એટલે કે જો
$\Gamma = \Setabs{!A}{\Gamma \Entails
!A}$ હોય.
\end{defn}

source_text:
\begin{defn}\ollabel{def:standard-model}
The \emph{standard model of arithmetic} is the !!{structure}~$\Struct
N$ defined as follows:
\begin{enumerate}
\item $\Domain N = \Nat$
\item $\Assign{\Obj 0}{N} = 0$
\item $\Assign{\Obj \prime}{N}(n) = n + 1$ for all $n \in \Nat$
\item $\Assign{\Obj +}{N}(n, m) = n + m$ for all $n, m \in \Nat$
\item $\Assign{\Obj \times}{N}(n, m) = n\cdot m$ for all $n, m \in \Nat$
\item $\Assign{\Obj <}{N} = \Setabs{\tuple{n, m}}{n \in \Nat, m \in
  \Nat, n < m}$
\end{enumerate}
\end{defn}

target_text:
\begin{defn}\ollabel{def:standard-model}
\emph{અંકગણિતનું પ્રમાણભૂત નિદર્શ} નીચે મુજબ
વ્યાખ્યાયિત !!{structure}~$\Struct N$ છે:
\begin{enumerate}
\item $\Domain N = \Nat$
\item $\Assign{\Obj 0}{N} = 0$
\item $\Assign{\Obj \prime}{N}(n) = n + 1$, દરેક $n \in \Nat$ માટે
\item $\Assign{\Obj +}{N}(n, m) = n + m$, દરેક $n, m \in \Nat$ માટે
\item $\Assign{\Obj \times}{N}(n, m) = n\cdot m$, દરેક $n, m \in \Nat$ માટે
\item $\Assign{\Obj <}{N} = \Setabs{\tuple{n, m}}{n \in \Nat, m \in
  \Nat, n < m}$
\end{enumerate}
\end{defn}

\begin{defn}
\emph{સાચું અંકગણિત}નો સિદ્ધાંત અંકગણિતના
પ્રમાણભૂત નિદર્શમાં સંતોષાતાં !!{sentence}sનો ગણ છે;
એટલે કે,
\[
\Th{TA} = \Setabs{!A}{\Sat{N}{!A}}.
\]
\end{defn}

source_text:
\begin{defn}
A theory~$\Gamma$ is \emph{axiomatized} by~$\Gamma_0$ iff
\[
\Gamma = \Setabs{!A}{\Gamma_0 \Entails !A}
\]
\end{defn}

target_text:
\begin{defn}
સિદ્ધાંત~$\Gamma$ એ~$\Gamma_0$ વડે
\emph{સ્વયંસિદ્ધીકૃત} છે ત્યારે અને માત્ર ત્યારે,
જ્યારે
\[
\Gamma = \Setabs{!A}{\Gamma_0 \Entails !A}
\]
હોય.
\end{defn}

source_text:
\begin{defn}
A theory $\Gamma$ is \emph{!!{complete}} iff for every
!!{sentence}~$!A$ in its language, either $\Gamma \Entails !A$ or
$\Gamma \Entails \lnot !A$.
\end{defn}

\begin{explain}
By the Completeness Theorem, $\Gamma \Entails !A$ iff $\Gamma \Proves
!A$, so $\Gamma$ is complete iff for every !!{sentence}~$!A$ in its
language, either $\Gamma \Proves !A$ or $\Gamma \Proves \lnot !A$.
\end{explain}

\begin{defn}
A set $X$ is \emph{!!{decidable}} iff there is a computational procedure
which on input~$x$ returns~$1$ if $x \in X$ and $0$ otherwise.
\end{defn}

target_text:
\begin{defn}
ગણ~$X$ \emph{!!{decidable}} છે ત્યારે
અને માત્ર ત્યારે, જ્યારે એવી સંગણકીય પ્રક્રિયા
હોય જે ઇનપુટ~$x$ માટે $x \in X$ હોય તો
$1$ અને અન્યથા~$0$ આપે.
\end{defn}

source_text:
\begin{defn}
A theory is \emph{!!{axiomatizable}} if it is axiomatized
by !!a{decidable} set of axioms.
\end{defn}

target_text:
\begin{defn}
સિદ્ધાંત \emph{!!{axiomatizable}} છે, જો
તે સ્વયંસિદ્ધ વાક્યોના !!a{decidable} ગણથી
સ્વયંસિદ્ધીકૃત હોય.
\end{defn}

source_text:
\begin{defn}
A set $X$ is called \emph{!!{computably enumerable}} (!!{c.e.} for
short) iff it is empty or it has a computable enumeration.
\end{defn}

target_text:
\begin{defn}
ગણ~$X$ \emph{!!{computably enumerable}}
(ટૂંકમાં~!!{c.e.}) કહેવાય છે ત્યારે અને માત્ર
ત્યારે, જ્યારે તે ખાલી હોય અથવા તેની
સંગણનીય પરિગણના હોય.
\end{defn}

source_text:
\begin{defn}
A !!{formula}~$!A(x_1, \dots, x_k, y)$ \emph{!!{represents}} the
function $f\colon \Nat^k \to \Nat$ in~$\Gamma$ iff whenever $f(n_1,
\dots, n_k) = m$, then
\begin{enumerate}
\item $\Gamma \Proves !A(\num{n_1}, \dots, \num{n_k}, \num{m})$, and
\item $\Gamma \Proves \lforall[y](!A(\num{n_1}, \dots, \num{n_k},
y) \lif y = \num{m})$.
\end{enumerate}
\end{defn}

target_text:
\begin{defn}
!!{formula}~$!A(x_1, \dots, x_k, y)$ એ
વિધેય~$f\colon \Nat^k \to \Nat$ને
$\Gamma$માં \emph{!!{represents}} છે
ત્યારે અને માત્ર ત્યારે, જ્યારે
$f(n_1, \dots, n_k)=m$ હોય ત્યારે
\begin{enumerate}
\item $\Gamma \Proves !A(\num{n_1}, \dots, \num{n_k}, \num{m})$, અને
\item $\Gamma \Proves \lforall[y](!A(\num{n_1}, \dots, \num{n_k},
y) \lif y = \num{m})$.
\end{enumerate}
\end{defn}

source_text:
\begin{defn}
A !!{formula}~$!A(x_1, \dots, x_k)$ \emph{!!{represents}} the
relation $R \subseteq \Nat^k$ iff,
\begin{enumerate}
\item whenever $R(n_1, \dots, n_k)$, $\Gamma \Proves !A(\num{n_1},
\dots, \num{n_k})$, and
\item whenever not $R(n_1, \dots, n_k)$, $\Gamma \Proves \lnot
!A(\num{n_1}, \dots, \num{n_k})$.
\end{enumerate}
\end{defn}

target_text:
\begin{defn}
!!{formula}~$!A(x_1, \dots, x_k)$ સંબંધ
$R \subseteq \Nat^k$ને એ જ સિદ્ધાંતમાં
\emph{!!{represents}}
છે ત્યારે અને માત્ર ત્યારે,
\begin{enumerate}
\item $R(n_1, \dots, n_k)$ હોય ત્યારે
  $\Gamma \Proves !A(\num{n_1},
\dots, \num{n_k})$, અને
\item $R(n_1, \dots, n_k)$ ન હોય ત્યારે
  $\Gamma \Proves \lnot
!A(\num{n_1}, \dots, \num{n_k})$.
\end{enumerate}
