source_text:
\begin{prop}
The property $\fn{Sent}(x)$ which holds iff $x$~is the G\"odel
number of !!a{sentence} is primitive recursive.
\end{prop}

target_text:
\begin{prop}
$x$ કોઈ !!a{sentence}ની ગડેલ-સંખ્યા
હોય ત્યારે અને માત્ર ત્યારે સત્ય થતો
ગુણધર્મ~$\fn{Sent}(x)$ આદિમ
પુનરાવર્તી છે.
\end{prop}

source_text:
\begin{proof}
A !!{sentence} is !!a{formula} without free occurrences of
!!{variable}s. So $\fn{Sent}(x)$ holds iff
\begin{multline*}
\bforall{i<\len{x}}{\bforall{z<x}{}}\\
(\bexists{j<z}{z=\Gn{\Obj v_j}} \lif \lnot\fn{FreeOcc}(x,z,i)).
\end{multline*}
\end{proof}

target_text:
\begin{proof}
!!{sentence} એ !!{variable}sની મુક્ત
ઘટના વિનાનું !!a{formula} છે. તેથી
$\fn{Sent}(x)$ ત્યારે અને માત્ર ત્યારે,
જ્યારે
\begin{multline*}
\bforall{i<\len{x}}{\bforall{z<x}{}}\\
(\bexists{j<z}{z=\Gn{\Obj v_j}} \lif \lnot\fn{FreeOcc}(x,z,i)).
\end{multline*}
\end{proof}

source_text:
\begin{proof}
We can then define a function $\fn{hSubst}$ by primitive recursion as
follows:
\begin{multline*}
\begin{aligned}
\fn{hSubst}(x, y, z, 0) & = \emptyseq \\
\fn{hSubst}(x, y, z, i+1) & =
\end{aligned}\\
\begin{cases}
\fn{hSubst}(x, y, z, i) \concat y & \text{if $\fn{FreeOcc}(x, z, i)$} \\
\fn{append}(\fn{hSubst}(x, y, z, i), (x)_{i}) & \text{otherwise.}
\end{cases}
\end{multline*}
$\fn{Subst}(x, y, z)$ can now be defined as $\fn{hSubst}(x, y, z, \len{x})$.
\end{proof}

target_text:
\begin{proof}
આદિમ પુનરાવર્તન વડે વિધેય~$\fn{hSubst}$
આ પ્રમાણે વ્યાખ્યાયિત કરી શકીએ:
\begin{multline*}
\begin{aligned}
\fn{hSubst}(x, y, z, 0) & = \emptyseq \\
\fn{hSubst}(x, y, z, i+1) & =
\end{aligned}\\
\begin{cases}
\fn{hSubst}(x, y, z, i) \concat y & \text{જો $\fn{FreeOcc}(x, z, i)$ હોય} \\
\fn{append}(\fn{hSubst}(x, y, z, i), (x)_{i}) & \text{અન્યથા.}
\end{cases}
\end{multline*}
હવે~$\fn{Subst}(x, y, z)$ને
$\fn{hSubst}(x, y, z, \len{x})$ તરીકે
વ્યાખ્યાયિત કરી શકીએ.
\end{proof}

