\end{defn}

\begin{lem}\ollabel{lem:omega-cons-G-unref}
If $\Th{T}$ is an $\omega$-consistent, !!{axiomatizable} theory
extending~$\Th{Q}$, then $\Th{T} \Proves/ \lnot !G_\Th{T}$.
\end{lem}

