source_text:
\begin{defn}[Variable Assignment]
A \emph{variable assignment}~$s$ for !!a{structure}~$\Struct{M}$ is a
function which maps each
\begin{enumerate}
\item object !!{variable}~$\Obj{v_i}$ to an element of~$\Domain M$,
  i.e., $s(\Obj{v_i}) \in \Domain{M}$
\item $n$-place relation variable~$\Obj{V_i^n}$ to an $n$-place
  relation on~$\Domain{M}$, i.e., $s(\Obj{V_i^n}) \subseteq \Domain{M}^n$;
\item $n$-place function variable~$\Obj{u_i^n}$ to an $n$-place
  function from $\Domain{M}$ to $\Domain{M}$, i.e.,
  $s(\Obj{u_i^n})\colon \Domain{M}^n \to \Domain{M}$;
\end{enumerate}
\end{defn}

target_text:
\begin{defn}[ચલ-નિયુક્તિ]
!!a{structure}~$\Struct{M}$ માટેની \emph{ચલ-નિયુક્તિ}~$s$ એવું
વિધેય છે જે દરેક
\begin{enumerate}
\item વસ્તુ-!!{variable}~$\Obj{v_i}$ને~$\Domain M$નો ઘટક આપે છે,
  એટલે $s(\Obj{v_i}) \in \Domain{M}$;
\item $n$-સ્થાની સંબંધ-ચલ~$\Obj{V_i^n}$ને~$\Domain{M}$ પરનો
  $n$-સ્થાની સંબંધ આપે છે, એટલે
  $s(\Obj{V_i^n}) \subseteq \Domain{M}^n$;
\item $n$-સ્થાની વિધેય-ચલ~$\Obj{u_i^n}$ને $\Domain{M}$માંથી
  $\Domain{M}$માં જતું $n$-સ્થાની વિધેય આપે છે, એટલે
  $s(\Obj{u_i^n})\colon \Domain{M}^n \to \Domain{M}$.
\end{enumerate}
\end{defn}

source_text:
\begin{explain}
!!^a{structure} assigns !!a{value} to each !!{constant} and
!!{function}, and a second-order variable assignment assigns objects and
functions to each object and function variable. Together, they let us
assign a value to every term.
\end{explain}

target_text:
\begin{explain}
!!^a{structure} દરેક !!{constant} અને !!{function}ને !!a{value}
આપે છે; દ્વિતીય-ક્રમ ચલ-નિયુક્તિ દરેક વસ્તુ-ચલને વસ્તુ, દરેક
વિધેય-ચલને વિધેય અને દરેક સંબંધ-ચલને સંબંધ આપે છે. આ બંને સાથે
મળીને દરેક પદનું મૂલ્ય નક્કી કરી શકાય છે.
\sourcecorrection{OLSOL-002}{સ્થિર અંગ્રેજી મૂળની આ સમજણમાં
ચલ-નિયુક્તિ દ્વારા વસ્તુ-ચલો અને વિધેય-ચલોને મળતા મૂલ્યો જણાવ્યાં
છે, પરંતુ ઉપરની વ્યાખ્યામાં આવરી લીધેલા સંબંધ-ચલોને મળતા સંબંધોનો
ઉલ્લેખ રહી ગયો છે. અહીં તે ત્રીજો પ્રકાર પણ સ્પષ્ટ કર્યો છે.}
\end{explain}

source_text:
\begin{defn}[\usetoken{S}{value} of a Term]
If $t$ is a term of the language~$\Lang L$, $\Struct M$ is
!!a{structure} for~$\Lang L$, and $s$ is !!a{variable} assignment
for~$\Struct M$, the \emph{!!{value}}~$\Value{t}{M}[s]$ is defined as
for first-order terms, plus the following clause:
\begin{quote}
\indcase{t}{\Atom{u}{t_1, \ldots, t_n}}{
\[
\Value{\indfrm}{M}[s] = s(u)(\Value{t_1}{M}[s], \ldots,
\Value{t_n}{M}[s]).
\]}
\end{quote}
\end{defn}

target_text:
\begin{defn}[પદનું \usetoken{S}{value}]
જો~$t$ ભાષા~$\Lang L$નું પદ હોય, $\Struct M$ એ~$\Lang L$ માટેની
!!a{structure} હોય અને~$s$ એ~$\Struct M$ માટેની !!a{variable}
નિયુક્તિ હોય, તો \emph{!!{value}}~$\Value{t}{M}[s]$ પ્રથમ-ક્રમ
પદોની જેમ જ, નીચેની વધારાની કલમ સાથે વ્યાખ્યાયિત થાય છે:
\begin{quote}
\indcase{t}{\Atom{u}{t_1, \ldots, t_n}}{
\[
\Value{\indfrm}{M}[s] = s(u)(\Value{t_1}{M}[s], \ldots,
\Value{t_n}{M}[s]).
\]}
\end{quote}
\end{defn}

source_text:
\begin{defn}[Satisfaction]
For second-order !!{formula}s~$!A$, the definition of satisfaction is
like \olref[fol][syn][sat]{defn:satisfaction} with the addition of:
\begin{enumerate}
\item \indcase{!A}{\Atom{X^n}{t_1, \dots, t_n}}{$\Sat{M}{\indfrm}[s]$
  iff $\langle \Value{t_1}{M}[s], \dots, \Value{t_n}{M}[s] \rangle \in
  s(X^n)$.}
\tagitem{prvAll}{%
  \indcase{!A}{\lforall[X][!B]}{$\Sat{M}{\indfrm}[s]$ iff for every $M
  \subseteq \Domain{M}^n$, $\Sat{M}{!B}[\Subst{s}{M}{X}]$.}}{}

\tagitem{prvEx}{%
  \indcase{!A}{\lexists[u][!B]}{$\Sat{M}{\indfrm}[s]$ iff for at least
  one $f\colon \Domain{M}^n \to \Domain{M}$ so that
  $\Sat{M}{!B}[\Subst{s}{f}{u}]$.}}{}
\end{enumerate}
\end{defn}

target_text:
\tagitem{prvEx}{%
  \indcase{!A}{\lexists[u][!B]}{$\Sat{M}{\indfrm}[s]$ ત્યારે અને
  માત્ર ત્યારે જ જ્યારે ઓછામાં ઓછા એક
  $f\colon \Domain{M}^n \to \Domain{M}$ માટે
  $\Sat{M}{!B}[\Subst{s}{f}{u}]$.}}{}
\end{enumerate}
\end{defn}

source_text:
\begin{prob}
  Show that in second-order logic $\lforall$ and~$\lif$ can define the other
  connectives:
  \begin{enumerate}
    \item Prove that in second-order logic $!A \land !B$ is equivalent
    to $\lforall[X][(!A \lif (!B \lif \lforall[x][X(x)])\lif
    \lforall[x][X(x)])]$.
    \item Find a second-order formula using only $\lforall$ and $\lif$
    equivalent to $!A \lor !B$.
  \end{enumerate}
\end{prob}

target_text:
\begin{prob}
  બતાવો કે દ્વિતીય-ક્રમ તર્કશાસ્ત્રમાં $\lforall$ અને~$\lif$ વડે
  બીજા સંયોજકો વ્યાખ્યાયિત કરી શકાય છે:
  \begin{enumerate}
    \item સાબિત કરો કે દ્વિતીય-ક્રમ તર્કશાસ્ત્રમાં $!A \land !B$ એ
    $\lforall[X][(!A \lif (!B \lif \lforall[x][X(x)])\lif
    \lforall[x][X(x)])]$ને સમકક્ષ છે.
    \item માત્ર $\lforall$ અને $\lif$ વાપરીને $!A \lor !B$ને
    સમકક્ષ દ્વિતીય-ક્રમ સૂત્ર શોધો.
  \end{enumerate}
\end{prob}

\begin{defn}
જો~$\Struct{M}$ એ ભાષા~$\Lang{L}$ માટેની !!a{structure} હોય, તો
સંબંધ~$R \subseteq \Domain{M}^2$ એ~$\Lang{L}$માં \emph{વ્યાખ્યેય}
છે જો એવું કોઈ !!{formula}~$!A_R(x, y)$ હોય જેમાં માત્ર $x$ અને~$y$
મુક્ત હોય અને $s(x) = a$ તથા $s(y) = b$ માટે $R(a, b)$, એટલે
$\tuple{a,b} \in R$, ત્યારે અને માત્ર ત્યારે જ જ્યારે
$\Sat{M}{!A_R(x, y)}[s]$.
\end{defn}

source_text:
\begin{prob}
Show that $\lforall[X][(X(x) \lif X(y))]$ (note:
$\lif$ not~$\liff$!) defines $\Id{\Domain{M}}$.
\end{prob}

target_text:
\begin{prob}
બતાવો કે $\lforall[X][(X(x) \lif X(y))]$ પણ~$\Id{\Domain{M}}$
વ્યાખ્યાયિત કરે છે (ધ્યાન આપો: અહીં $\lif$ છે, $\liff$ નહિ!).
\end{prob}

source_text:
\begin{prop}
$\Sat{M}{\fn{Inf}}$ iff $\Domain{M}$ is infinite.
\end{prop}

target_text:
\begin{prop}
$\Sat{M}{\fn{Inf}}$ ત્યારે અને માત્ર ત્યારે જ જ્યારે~$\Domain{M}$
અનંત હોય.
\end{prop}

source_text:
\begin{proof}
$\Sat{M}{\fn{Inf}}$ iff
  $\Sat{M}{\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif \eq[x][y])]]
    \land \lexists[y][\lforall[x][\eq/[y][u(x)]]]}[s]$ for
  some~$s$. If it does, $s(u)$ is !!a{injective} function, and some $y
  \in \Domain{M}$ is not in the range of~$s(u)$. Conversely, if there
  is !!a{injective} $f\colon \Domain{M} \to \Domain{M}$ with $\ran{f}
  \neq \Domain{M}$, then $s(u) = f$ is such a variable
  assignment.
\end{proof}

\begin{prop}
$\Sat{M}{\fn{Count}}$ iff $\Domain{M}$ is !!{enumerable}.
\end{prop}

target_text:
\begin{prop}
$\Sat{M}{\fn{Count}}$ ત્યારે અને માત્ર ત્યારે જ જ્યારે~$\Domain{M}$
!!{enumerable} હોય.
\end{prop}

source_text:
\begin{prob}
The !!{sentence} $\fn{Inf} \land \fn{Count}$ is true in all and only
!!{denumerable} domains.  Adjust the definition of $\fn{Count}$ so
that it becomes a different !!{sentence} that directly expresses that
the domain is !!{denumerable}, and prove that it does.
\end{prob}

target_text:
\begin{prob}
!!{sentence}~$\fn{Inf} \land \fn{Count}$ બધા અને માત્ર
!!{denumerable} વ્યાપકક્ષેત્રોમાં સાચું છે. $\fn{Count}$ની વ્યાખ્યા
એવી બદલો કે નવું !!{sentence} વ્યાપકક્ષેત્ર !!{denumerable} છે એવું
સીધું વ્યક્ત કરે, અને તે કરે છે એમ સાબિત કરો.
\end{prob}

source_text:
\begin{thm}
\ollabel{thm:sol-pa-standard}
If $\Sat{M}{\Th{PA^2}}$ then $\Domain{M} =
\Setabs{\Value{\num{n}}{M}}{n \in \Nat}$.
\end{thm}

target_text:
\begin{thm}
\ollabel{thm:sol-pa-standard}
જો $\Sat{M}{\Th{PA^2}}$ હોય, તો $\Domain{M} =
\Setabs{\Value{\num{n}}{M}}{n \in \Nat}$.
\end{thm}

source_text:
We have that $\Sat{M}{X(\Obj 0) \land \lforall[x][(X(x) \lif X(x'))]}[s]$.
Consequently, $\Sat{M}{\lforall[x][X(x)]}[s]$. But that means that for
every $x \in \Domain{M}$ we have $x \in s(X) = N$. So, $\Domain{M}
\subseteq N$.
\end{proof}

\begin{cor}
\ollabel{cor:sol-pa-categorical}
Any two models of~$\Th{PA^2}$ are isomorphic.
\end{cor}

target_text:
\begin{cor}
\ollabel{cor:sol-pa-categorical}
$\Th{PA^2}$નાં કોઈપણ બે નિદર્શો એકરૂપ છે.
\end{cor}

source_text:
\begin{proof}
By \olref{thm:sol-pa-standard}, the domain of any model of $\Th{PA^2}$
is exhausted by $\Value{\num{n}}{M}$. Any such model is also a model
of~$\Th{Q}$. By \olref[mod][mar][stm]{prop:thq-standard}, any such
model is standard, i.e., isomorphic to~$\Struct{N}$.
\end{proof}

\begin{prop}\ollabel{prop:sol-pa-definable}
Let $\Th{PA^{2\dagger}}$ be the second-order theory containing the
first two arithmetical axioms (the successor axioms) and the
second-order induction axiom. Then $\le$, $+$, and $\times$ are definable
in $\Th{PA^{2\dagger}}$.
\end{prop}

\begin{prob}
Complete the proof of \olref[sol][met][spa]{prop:sol-pa-definable}.
\end{prob}

target_text:
\begin{prob}
\olref[sol][met][spa]{prop:sol-pa-definable}ની સાબિતી પૂરી કરો.
\end{prob}

source_text:
\begin{thm}
\ollabel{thm:sol-undecidable}
Second-order logic is undecidable.
\end{thm}

target_text:
\begin{thm}
\ollabel{thm:sol-undecidable}
દ્વિતીય-ક્રમ તર્કશાસ્ત્ર અનિર્ણેય છે.
\end{thm}

source_text:
\begin{proof}
A first-order !!{sentence} is valid in first-order logic iff it is
valid in second-order logic, and first-order logic is undecidable.
\end{proof}

target_text:
\begin{proof}
પ્રથમ-ક્રમ !!{sentence} પ્રથમ-ક્રમ તર્કશાસ્ત્રમાં પ્રમાણભૂત ત્યારે
અને માત્ર ત્યારે જ હોય જ્યારે તે દ્વિતીય-ક્રમ તર્કશાસ્ત્રમાં
પ્રમાણભૂત હોય; વળી પ્રથમ-ક્રમ તર્કશાસ્ત્ર અનિર્ણેય છે.
\end{proof}

source_text:
\begin{thm}
\ollabel{cor:sol-not-axiomatizable}
There is no sound and complete !!{derivation} system for second-order logic.
\end{thm}

target_text:
\begin{thm}
\ollabel{cor:sol-not-axiomatizable}
દ્વિતીય-ક્રમ તર્કશાસ્ત્ર માટે અસરકારક રીતે આપેલું એવું કોઈ યથાર્થ અને
પૂર્ણ !!{derivation} તંત્ર નથી.
\end{thm}
\sourcecorrection{OLSOL-008}{સ્થિર અંગ્રેજી મૂળમાં અહીં કોઈપણ યથાર્થ
અને પૂર્ણ નિષ્પત્તિ-તંત્ર નથી એમ નિઃશરત કહેવાયું છે. અસરકારક રીતે
આપેલું તંત્ર હોવાની શરત જરૂરી છે: અસરકારકતાની શરત વિના બધાં પ્રમાણભૂત
વાક્યોને જ સ્વયંસિદ્ધિઓ તરીકે લઈ શકાય. નીચેની સાબિતી સંગણનીય
પરિગણનાનો વિરોધાભાસ ઉત્પન્ન કરે છે, તેથી આ શરત સ્પષ્ટ કરી છે.}

source_text:
\begin{thm}
\ollabel{thm:sol-undecidable}
Second-order logic is not compact.
\end{thm}

target_text:
\begin{thm}
\ollabel{thm:sol-not-compact}
દ્વિતીય-ક્રમ તર્કશાસ્ત્ર સઘન નથી.
\end{thm}
\sourcecorrection{OLSOL-011}{સ્થિર અંગ્રેજી મૂળમાં આ પ્રમેયનું
\texttt{thm:sol-undecidable} લેબલ અગાઉના અનિર્ણેયતા પ્રમેયનું લેબલ
જ ફરી વાપરે છે. બે અલગ પરિણામોને એક જ લેબલ ન રહે તે માટે અહીં
\texttt{thm:sol-not-compact} આપ્યું છે.}

source_text:
\begin{prob}
Give an example of a set~$\Gamma$ and !!a{sentence}~$!A$ so that
$\Gamma \Entails !A$ but for every finite subset~$\Gamma_0 \subseteq
\Gamma$, $\Gamma_0 \Entails/ !A$.
\end{prob}

target_text:
\begin{prob}
એવો ગણ~$\Gamma$ અને !!a{sentence}~$!A$નું ઉદાહરણ આપો કે
$\Gamma \Entails !A$, પરંતુ દરેક સાન્ત ઉપગણ~$\Gamma_0 \subseteq
\Gamma$ માટે $\Gamma_0 \Entails/ !A$.
\end{prob}

\begin{explain}
(અધોગામી) લેવેનહાઇમ--સ્કોલેમ પ્રમેય કહે છે કે !!{sentence}sના જે
ગણને અનંત નિદર્શ હોય, તેને !!a{enumerable} નિદર્શ પણ હોય છે. આ
પ્રમેય પણ પૂર્ણતા પ્રમેયનું પરિણામ છે: પૂર્ણતાની સાબિતી
!!{sentence}sના કોઈપણ સુસંગત ગણ માટે નિદર્શ રચે છે, અને તે નિદર્શ
!!{enumerable} હોય છે. ઊર્ધ્વગામી લેવેનહાઇમ--સ્કોલેમ પ્રમેય પણ છે;
તે ખાતરી આપે છે કે !!{sentence}sના ગણને !!a{denumerable} નિદર્શ
હોય તો તેને !!a{nonenumerable} નિદર્શ પણ હોય છે. દ્વિતીય-ક્રમ
તર્કશાસ્ત્રમાં બંને પ્રમેયો નિષ્ફળ જાય છે.
\end{explain}

source_text:
\begin{thm}
\ollabel{thm:sol-no-ls} The L\"owenheim--Skolem Theorem fails for
second-order logic: There are !!{sentence}s with infinite models but
no !!{enumerable} models.
\end{thm}

target_text:
\begin{thm}
\ollabel{thm:sol-no-ls} દ્વિતીય-ક્રમ તર્કશાસ્ત્રમાં લેવેનહાઇમ--સ્કોલેમ
પ્રમેય નિષ્ફળ જાય છે: એવા !!{sentence}s છે જેમને અનંત નિદર્શો છે,
પણ કોઈ !!{enumerable} નિદર્શ નથી.
\end{thm}

source_text:
\begin{thm}
There are !!{sentence}s with !!{denumerable} but no
!!{nonenumerable} models.
\end{thm}

target_text:
\begin{thm}
એવા !!{sentence}s છે જેમને !!{denumerable} નિદર્શો છે,
પણ કોઈ !!{nonenumerable} નિદર્શ નથી.
\end{thm}

source_text:
\begin{proof}
$\fn{Count} \land \fn{Inf}$ is true in $\Nat$ but not in any
  !!{structure}~$\Struct{M}$ with $\Domain{M}$ !!{nonenumerable}.
\end{proof}

target_text:
\begin{proof}
$\fn{Count} \land \fn{Inf}$ એ~$\Nat$માં સાચું છે, પરંતુ
જે !!{structure}~$\Struct{M}$ માટે~$\Domain{M}$
!!{nonenumerable} હોય તેમાં સાચું નથી.
\end{proof}

source_text:
\begin{prop}
The !!{formula} $\lforall[x][(X(x) \lif Y(x))]$ defines the subset
relation, i.e., $\Sat{M}{\lforall[x][(X(x) \lif Y(x))]}[s]$ iff $s(X)
\subseteq s(Y)$.
\end{prop}

target_text:
\begin{prop}
!!{formula}~$\lforall[x][(X(x) \lif Y(x))]$ ઉપગણ-સંબંધ
વ્યાખ્યાયિત કરે છે: $\Sat{M}{\lforall[x][(X(x) \lif Y(x))]}[s]$
ત્યારે અને માત્ર ત્યારે જ જ્યારે $s(X) \subseteq s(Y)$.
\end{prop}

source_text:
\begin{prop}
The !!{formula} $\lforall[x][(X(x) \liff Y(x))]$ defines the identity
relation on sets, i.e., $\Sat{M}{\lforall[x][(X(x) \liff Y(x))]}[s]$
iff $s(X) = s(Y)$.
\end{prop}

target_text:
\begin{prop}
!!{formula}~$\lforall[x][(X(x) \liff Y(x))]$ ગણો પરનો
તાદાત્મ્ય-સંબંધ વ્યાખ્યાયિત કરે છે: $\Sat{M}{\lforall[x][(X(x)
\liff Y(x))]}[s]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે $s(X) = s(Y)$.
\end{prop}

source_text:
\begin{prop}
The !!{formula} $\lexists[x][X(x)]$ defines the property of being
non-empty, i.e., $\Sat{M}{\lexists[x][X(x)]}[s]$ iff $s(X) \neq
\emptyset$.
\end{prop}

target_text:
\begin{prop}
!!{formula}~$\lexists[x][X(x)]$ અરિક્ત હોવાનો ગુણધર્મ વ્યાખ્યાયિત
કરે છે: $\Sat{M}{\lexists[x][X(x)]}[s]$ ત્યારે અને માત્ર ત્યારે જ
જ્યારે $s(X) \neq \emptyset$.
\end{prop}

source_text:
\begin{prop}
The formula
\begin{multline*}
  \lexists[u][(\lforall[x][(X(x) \lif Y(u(x)))] \land {}\\
    \lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif \eq[x][y])]]
  \land {} \\\lforall[y][(Y(y) \lif \lexists[x][(X(x)
      \land \eq[y][u(x)])])])]
\end{multline*}
defines the relation of being equinumerous with.
\end{prop}

target_text:
\begin{prop}
નીચેનું સૂત્ર
\begin{multline*}
  \lexists[u][(\lforall[x][(X(x) \lif Y(u(x)))] \land {}\\
    \lforall[x][\lforall[y][((X(x) \land X(y) \land \eq[u(x)][u(y)]) \lif \eq[x][y])]]
  \land {} \\\lforall[y][(Y(y) \lif \lexists[x][(X(x)
      \land \eq[y][u(x)])])])]
\end{multline*}
સામ્ય-સંબંધ વ્યાખ્યાયિત કરે છે.
\end{prop}
\sourcecorrection{OLSOL-014}{સ્થિર અંગ્રેજી મૂળનું સૂત્ર~$u$ને આખા
વ્યાપકક્ષેત્ર પર એક-એક માગે છે. પરંતુ અનંત વ્યાપકક્ષેત્રમાં જો~$X$ તેનો ઉચિત
ઉપગણ અને~$Y$ આખું વ્યાપકક્ષેત્ર હોય, તો~$X$ તથા~$Y$ સામ્ય હોવા
છતાં~$X$ પરથી~$Y$ પરનું વ્યાપ્ત એક-એક વિધેય બહારના ઘટકો સુધી
આખા વ્યાપકક્ષેત્ર પર એક-એક રીતે વિસ્તારી શકાતું નથી. અહીં
એક-એકતાની શરત~$X$ પર જ મૂકી છે.}

