source_text:
\begin{explain}
Just as we can express that the domain is finite or infinite,
!!{enumerable} or !!{nonenumerable}, we can define the property of a
subset of~$\Domain{M}$ being finite or infinite, !!{enumerable} or
!!{nonenumerable}.
\end{explain}

target_text:
\begin{explain}
વ્યાપકક્ષેત્ર સાન્ત કે અનંત, !!{enumerable} કે !!{nonenumerable}
છે એવું વ્યક્ત કરી શકીએ છીએ. તેવી જ રીતે~$\Domain{M}$નો કોઈ ઉપગણ
સાન્ત કે અનંત, !!{enumerable} કે !!{nonenumerable} છે તે ગુણધર્મ
પણ વ્યાખ્યાયિત કરી શકીએ છીએ.
\end{explain}

source_text:
\begin{prop}
The formula $\fn{Inf}(X) \ident$
\begin{multline*}
\lexists[u][(\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif 
      \eq[x][y])]] \land {} \\\lexists[y][(X(y) \land \lforall[x][(X(x)
      \lif \eq/[y][u(x)])]])]
\end{multline*}
is satisfied with respect to a variable assignment~$s$ iff $s(X)$ is
infinite.
\end{prop}

\begin{prop}
The formula $\fn{Count}(X) \ident $
\begin{multline*}
\lexists[z][\lexists[u][(X(z) \land 
    \lforall[x][(X(x) \lif X(u(x)))] \land {} \\ \lforall[Y][((Y(z) \land
      \lforall[x][(Y(x) \lif Y(u(x)))]) \lif X = Y])]])
\end{multline*}
is satisfied with respect to a variable assignment~$s$ iff $s(X)$ is
!!{enumerable}.
\end{prop}

\begin{defn}
If $R \subseteq \Domain{M}^2$, then \emph{$x$ $R$-codes} $\Setabs{y
  \in \Domain{M}}{R(x, y)}$.
\end{defn}

target_text:
\begin{defn}
જો $R \subseteq \Domain{M}^2$ હોય, તો \emph{$x$ એ~$R$ વડે}
$\Setabs{y \in \Domain{M}}{R(x, y)}$ને \emph{સંકેતિત કરે છે}.
\end{defn}

source_text:
\begin{prop}
The !!{formula}
  \[
  \fn{Codes}(x, R, Z) \ident \lforall[y][(Z(y) \liff
    R(x, y))]
  \]
expresses that $s(x)$ $s(R)$-codes $s(Z)$.  The
!!{formula} 
\begin{multline*}
  \fn{Pow}(Y, R, X) \ident \\
  \lforall[Z][(Z \subseteq X \lif \lexists[x][(Y(x) \land
    \fn{Codes}(x, R, Z))])] \land {} \\ \lforall[x][(Y(x) \lif
  \lforall[Z][(\fn{Codes}(x, R, Z) \lif Z \subseteq X)]]
\end{multline*}
expresses that $s(Y)$ $s(R)$-codes the power set of~$s(X)$, i.e., the
elements of $s(Y)$ $s(R)$-code exactly the subsets of $s(X)$.
\end{prop}

target_text:
\begin{prop}
!!{formula}
  \[
  \fn{Codes}(x, R, Z) \ident \lforall[y][(Z(y) \liff
    R(x, y))]
  \]
એ વ્યક્ત કરે છે કે $s(x)$ એ~$s(R)$ વડે~$s(Z)$ને સંકેતિત કરે છે.
નીચેનું !!{formula}
\begin{multline*}
  \fn{Pow}(Y, R, X) \ident \\
  \lforall[Z][(Z \subseteq X \lif \lexists[x][(Y(x) \land
    \fn{Codes}(x, R, Z))])] \land {} \\ \lforall[x][(Y(x) \lif
  \lforall[Z][(\fn{Codes}(x, R, Z) \lif Z \subseteq X)])]
\end{multline*}
એ વ્યક્ત કરે છે કે $s(Y)$ એ~$s(R)$ વડે~$s(X)$ના શક્તિસમૂહને
સંકેતિત કરે છે: $s(Y)$ના ઘટકો~$s(R)$ વડે~$s(X)$ના બધા અને માત્ર
ઉપગણોને સંકેતિત કરે છે.
\end{prop}
\sourcecorrection{OLSOL-018}{સ્થિર અંગ્રેજી મૂળના~$\fn{Pow}$
સૂત્રના બીજા સંયોજકમાં~$Y(x)$થી શરૂ થતો કૌંસ બંધ થતો નથી.
અહીં અંતે એક બંધ કૌંસ ઉમેર્યો છે, જેથી બહારનું નિહિતાર્થ અને બંને
સર્વપરિમાણકો યોગ્ય રીતે બંધ થાય.}

source_text:
\begin{prop}
The sentence
\begin{multline*}
  \lforall[X][\lforall[Y][\lforall[R][(\fn{Pow}(Y, R, X) \lif \\
      \lnot \lexists[u][(\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif
            \eq[x][y])]] \land {}\\
        \lforall[x][(Y(x) \lif X(u(x)))])])]]]
\end{multline*}
is valid.
\end{prop}

target_text:
\begin{prop}
નીચેનું વાક્ય
\begin{multline*}
  \lforall[X][\lforall[Y][\lforall[R][(\fn{Pow}(Y, R, X) \lif \\
      \lnot \lexists[u][(\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif
            \eq[x][y])]] \land {}\\
