source_text:
\begin{prop}
If $\cardle{\Real}{\Domain{M}}$, then the !!{formula}
\begin{multline*}
\fn{Cont}(Y) \ident 
\lexists[X][\lexists[R][((\fn{Aleph}_0(X) \land
      \fn{Pow}(Y, R, X)) \land \\ 
      \lforall[x][\lforall[y][((Y(x) \land {} 
      Y(y) \land \lforall[z][R(x,z) \liff R(y,z)]) \lif \eq[x][y])]])]]
\end{multline*}
expresses that $\cardeq{s(Y)}{\Real}$.
\end{prop}

target_text:
\begin{prop}
જો $\cardle{\Real}{\Domain{M}}$ હોય, તો નીચેનું !!{formula}
\begin{multline*}
\fn{Cont}(Y) \ident
\lexists[X][\lexists[R][((\fn{Aleph}_0(X) \land
      \fn{Pow}(Y, R, X)) \land \\ 
      \lforall[x][\lforall[y][((Y(x) \land {}
      Y(y) \land \lforall[z][R(x,z) \liff R(y,z)]) \lif \eq[x][y])]])]]
\end{multline*}
$\cardeq{s(Y)}{\Real}$ વ્યક્ત કરે છે.
\end{prop}

source_text:
\begin{prop}
$\cardeq{\Domain{M}}{\Real}$ iff
\begin{multline*}
  \Sat{M}{\lexists[X][\lexists[Y][\lexists[R][(\fn{Aleph}_0(X) \land \fn{Pow}(Y, R, X) \land \\
          \lexists[u][(\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif \eq[x][y])]] \land {} \\\lforall[y][(Y(y) \lif \lexists[x][\eq[y][u(x)]])])])]]]}.
        \end{multline*}
  \end{prop}

target_text:
\begin{prop}
$\cardeq{\Domain{M}}{\Real}$ ત્યારે અને માત્ર ત્યારે જ જ્યારે
\begin{multline*}
  \Sat{M}{\lexists[Y][(\fn{Cont}(Y) \land \\
          \lexists[u][(\lforall[x][\lforall[y][(\eq[u(x)][u(y)] \lif \eq[x][y])]] \land {} \\
\lforall[y][(Y(y) \liff \lexists[x][\eq[y][u(x)]])])])]}.
\end{multline*}
\end{prop}
\sourcecorrection{OLSOL-020}{સ્થિર અંગ્રેજી મૂળનું અહીંનું વાક્ય
માત્ર~$Y$ શક્તિસમૂહને સંકેતિત કરે છે અને~$Y$ એ~$u$ની છબીનો
ઉપગણ છે એમ માગે છે; ઓળખ-વિધેયથી આ બીજી શરત સહેલાઈથી મળે છે,
અટલે વાક્ય મોટા વ્યાપકક્ષેત્રોમાં પણ સાચું થઈ શકે છે. વળી~$Y$
પર સંકેતીકરણ એક-એક છે તેવી શરત નથી. અહીં~$\fn{Cont}(Y)$થી
$Y$નું કદ સાતત્યક જેટલું નિશ્ચિત કર્યું છે અને~$u$નું મૂલ્યસમૂહ
બરાબર~$Y$ રાખ્યું છે, જેથી આખા વ્યાપકક્ષેત્રનું કદ પણ એટલું જ થાય.}

source_text:
\begin{explain}
The Continuum Hypothesis is the statement that the size of the
continuum is the first !!{nonenumerable} cardinality, i.e, that
$\Pow{\Nat}$ has size~$\aleph_1$. 
\end{explain}

target_text:
\begin{explain}
સાતત્યક પરિકલ્પના એવું વિધાન છે કે સાતત્યકનું કદ પહેલું
!!{nonenumerable} કાર્ડિનલ કદ છે, એટલે~$\Pow{\Nat}$નું
કદ~$\aleph_1$ છે.
\end{explain}

source_text:
\begin{prop}
The Continuum Hypothesis is true iff \[\fn{CH} \ident
\lforall[X][(\fn{Aleph}_1(X) \liff \fn{Cont}(X))]\] is valid.
\end{prop}

target_text:
\begin{prop}
સાતત્યક પરિકલ્પના સાચી છે ત્યારે અને માત્ર ત્યારે જ જ્યારે
\[\fn{CH} \ident
\lforall[X][(\fn{Aleph}_1(X) \liff \fn{Cont}(X))]\]
પ્રમાણભૂત હોય.
\end{prop}

source_text:
\begin{prop}
The Continuum Hypothesis is false iff \[\fn{NCH} \ident
\lforall[X][(\fn{Cont}(X) \lif \lexists[Y][(Y \subseteq X \land \lnot
    \fn{Count}(Y) \land \lnot \cardeq{X}{Y})])]\] is valid.
\end{prop}

