source_text:
\begin{defn}[Change of bound variable, $\aconvone$]
  If a term $M$ contains an occurrence of $\lambd[x][N]$, $y \notin
  \FV{N}$, and $\Subst{N}{y}{x}$ is defined, then replacing this occurrence
  by 
  \begin{equation*}
    \lambd[y][\Subst{N}{y}{x}]
  \end{equation*}
  resulting in $M'$ is called a \emph{change of bound variable}, written
  as $M \redone[\alpha] M'$.
\end{defn}

target_text:
\begin{defn}[બદ્ધ ચલનું નામ બદલવું, $\aconvone$]
  પદ~$M$માં~$\lambd[x][N]$ની કોઈ ઘટના હોય, $x\neq y$,
  $y \notin
  \FV{N}$ હોય અને~$\Subst{N}{y}{x}$ વ્યાખ્યાયિત હોય તો
  તે ઘટનાને
  \begin{equation*}
    \lambd[y][\Subst{N}{y}{x}]
  \end{equation*}
  વડે બદલીને~$M'$ મળે તેને \emph{બદ્ધ ચલનું નામ બદલવું}
  કહીએ છીએ અને~$M \redone[\alpha] M'$ લખીએ છીએ.
\sourcecorrection{OLLAM-019}{સ્થિર અંગ્રેજી મૂળની પહેલી
વ્યાખ્યામાં~$x\neq y$ની શરત નથી, પરંતુ આગળની બંને સમકક્ષ
વ્યાખ્યાઓમાં તે છે. અહીં નામ ખરેખર બદલાય તે માટે એ શરત
સ્પષ્ટ મૂકી છે.}
\end{defn}

source_text:
\begin{defn}[Compatibility of relation]
  A relation $R$ on terms is said to be \emph{compatible}
  if it satisfies following conditions:
  \begin{enumerate}
  \item If $R N N'$ then $R \lambd[x][N] \lambd[x][N']$
  \item If $R P P'$ then $R (PQ) (P'Q)$
  \item If $R Q Q'$ then $R (PQ) (PQ')$
  \end{enumerate}
\end{defn}

target_text:
\begin{defn}[સંબંધની રચના-સુસંગતતા]
  પદો પરનો સંબંધ~$R$ નીચેની શરતો સંતોષે તો તેને
  \emph{રચના-સુસંગત} કહીએ છીએ:
  \begin{enumerate}
  \item જો $R N N'$ હોય તો $R \lambd[x][N] \lambd[x][N']$.
  \item જો $R P P'$ હોય તો $R (PQ) (P'Q)$.
  \item જો $R Q Q'$ હોય તો $R (PQ) (PQ')$.
  \end{enumerate}
\end{defn}

source_text:
Thus let's rephrase the definition:
\begin{defn}[Change of bound variable, $\aconvone$]
  \emph{Change of bound variable} ($\redone[\alpha]$) is 
  the smallest compatible relation on terms satisfying following
  condition:
  \begin{align*}
    &\lambd[x][N] \redone[\alpha] \lambd[y][\Subst{N}{y}{x}] && \text{if
      $x \neq y$, $y \notin \FV{N}$} \\
    & &&\text{and $\Subst{N}{y}{x}$ is defined}
  \end{align*}
\end{defn}

target_text:
આથી વ્યાખ્યા ફરી આ રીતે કહી શકાય:
\begin{defn}[બદ્ધ ચલનું નામ બદલવું, $\aconvone$]
  \emph{બદ્ધ ચલનું નામ બદલવાનો} સંબંધ~($\redone[\alpha]$)
  પદો પરનો સૌથી નાનો રચના-સુસંગત સંબંધ છે જે નીચેની
  શરત સંતોષે છે:
  \begin{align*}
    &\lambd[x][N] \redone[\alpha] \lambd[y][\Subst{N}{y}{x}] && \text{જો
      $x \neq y$, $y \notin \FV{N}$ હોય} \\
    & &&\text{અને $\Subst{N}{y}{x}$ વ્યાખ્યાયિત હોય}
  \end{align*}
\end{defn}

source_text:
\begin{defn}[Change of bound variable, $\aconvone$] \ollabel{defn:aconvone}
  \emph{Change of bound variable} ($\aconvone$) is inductively
  defined as follows:
  \begin{enumerate}
  \item If $N \aconvone N'$ then $\lambd[x][N] \aconvone
    \lambd[x][N']$ \ollabel{defn:aconvone1}
  \item If $P \aconvone P'$ then $(PQ) \aconvone (P'Q)$ \ollabel{defn:aconvone2}
  \item If $Q \aconvone Q'$ then $(PQ) \aconvone (PQ')$ \ollabel{defn:aconvone3}
  \item If $x \neq y$, $y \notin \FV{N}$ and $\Subst{N}{y}{x}$ is defined, then
    $\lambd[x][N] \redone[\alpha] \lambd[y][\Subst{N}{y}{x}]$.
    \ollabel{defn:aconvone4}
  \end{enumerate}
\end{defn}

target_text:
\begin{defn}[બદ્ધ ચલનું નામ બદલવું, $\aconvone$] \ollabel{defn:aconvone}
  \emph{બદ્ધ ચલનું નામ બદલવાનો} સંબંધ~($\aconvone$)
  આગમનથી આ રીતે વ્યાખ્યાયિત થાય છે:
  \begin{enumerate}
  \item જો $N \aconvone N'$ હોય તો $\lambd[x][N] \aconvone
    \lambd[x][N']$. \ollabel{defn:aconvone1}
  \item જો $P \aconvone P'$ હોય તો $(PQ) \aconvone (P'Q)$.
    \ollabel{defn:aconvone2}
  \item જો $Q \aconvone Q'$ હોય તો $(PQ) \aconvone (PQ')$.
    \ollabel{defn:aconvone3}
  \item જો $x \neq y$, $y \notin \FV{N}$ અને~$\Subst{N}{y}{x}$
    વ્યાખ્યાયિત હોય તો
    $\lambd[x][N] \redone[\alpha] \lambd[y][\Subst{N}{y}{x}]$.
    \ollabel{defn:aconvone4}
  \end{enumerate}
\end{defn}

source_text:
\begin{defn}[$\alpha$-conversion, $\aconv$] \ollabel{defn:aconv}
  \emph{$\alpha$-conversion} ($\aconv$) is inductively defined as follows:
  \begin{enumerate}
  \item If $P \aconv Q$ and $Q \aconv R$, then $P \aconv R$.
    \ollabel{defn:aconv1}
  \item If $P \aconvone Q$, then $P \aconv Q$. \ollabel{defn:aconv2}
  \item $P \aconv P$. \ollabel{defn:aconv3}
  \end{enumerate}
\end{defn}

target_text:
\begin{defn}[$\alpha$-રૂપાંતરણ, $\aconv$] \ollabel{defn:aconv}
  \emph{$\alpha$-રૂપાંતરણ}~($\aconv$) આગમનથી આ રીતે
  વ્યાખ્યાયિત થાય છે:
  \begin{enumerate}
  \item જો $P \aconv Q$ અને~$Q \aconv R$ હોય તો
    $P \aconv R$. \ollabel{defn:aconv1}
  \item જો $P \aconvone Q$ હોય તો $P \aconv Q$.
    \ollabel{defn:aconv2}
  \item $P \aconv P$. \ollabel{defn:aconv3}
  \end{enumerate}
\end{defn}

source_text:
\begin{prob}
  Are the following pairs of terms $\alpha$-convertible?
  \begin{enumerate}
  \item $\lambd[x][\lambd[y][x]]$ and $\lambd[y][\lambd[x][y]]$
  \item $\lambd[x][\lambd[y][x]]$ and $\lambd[c][\lambd[b][a]]$
  \item $\lambd[x][\lambd[y][x]]$ and $\lambd[c][\lambd[b][a]]$
  \end{enumerate}
\end{prob}

target_text:
\begin{prob}
  નીચેની પદ-જોડીઓ $\alpha$-રૂપાંતરણથી એકબીજામાં બદલી શકાય છે?
  \begin{enumerate}
  \item $\lambd[x][\lambd[y][x]]$ અને $\lambd[y][\lambd[x][y]]$
  \item $\lambd[x][\lambd[y][x]]$ અને $\lambd[c][\lambd[b][a]]$
  \item $\lambd[x][\lambd[y][x]]$ અને $\lambd[c][\lambd[b][a]]$
  \end{enumerate}
\sourcecorrection{OLLAM-021}{સ્થિર અંગ્રેજી મૂળમાં આ
અભ્યાસપ્રશ્નની બીજી અને ત્રીજી જોડી એકસરખી છે. અનુમાનથી
કોઈ નવી જોડી ન ઘડતાં બંને મૂળ મુજબ જાળવી છે.}
\end{prob}

source_text:
\begin{lem}\ollabel{lem:fv-one}
  If $P \aconvone Q$ then $\FV{P} = \FV{Q}$.
\end{lem}

target_text:
\begin{lem}\ollabel{lem:fv-one}
  $P \aconvone Q$ હોય તો $\FV{P} = \FV{Q}$.
\end{lem}

source_text:
\begin{proof}
  By induction on the !!{derivation} of $P \aconvone Q$.
  \begin{enumerate}
  \item If the last rule is \olref{defn:aconvone4}, then $P$ is of the
    form $\lambd[x][N]$ and $Q$ of the form
    $\lambd[y][\Subst{N}{y}{x}]$, with $x \neq y$, $y \notin \FV{N}$
    and $\Subst{N}{y}{x}$ defined. We distinguish cases according to
    whether $x \in \FV{N}$:
    \begin{enumerate}
    \item If $x \in FV(N)$, then:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]} &=
        \FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = ((\FV{N} \setminus \{x\}) \cup \{y\}) \setminus \{y\}
         && \text{ by \olref[sub]{thm:infv}} \\
        & = \FV{N} \setminus \{x\} \\
        & = \FV{\lambd[x][N]}
      \end{align*}
    \item If $x \notin FV(N)$, then:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]}
        & = FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = \FV{N} \setminus \{x\}
         && \text{by \olref[sub]{thm:notinfv}} \\
        & = \FV{\lambd[x][N]}.
      \end{align*}
    \end{enumerate}
  \item The other three cases are left as exercises. 
  \end{enumerate}
\end{proof}

target_text:
\begin{proof}
  $P \aconvone Q$ની !!{derivation} પર આગમનથી.
  \begin{enumerate}
  \item છેલ્લો નિયમ~\olref{defn:aconvone4} હોય તો~$P$
    એ~$\lambd[x][N]$ અને~$Q$ એ
    $\lambd[y][\Subst{N}{y}{x}]$ સ્વરૂપના છે; અહીં
    $x \neq y$, $y \notin \FV{N}$ અને~$\Subst{N}{y}{x}$
    વ્યાખ્યાયિત છે. હવે~$x \in \FV{N}$ છે કે નહીં તે
    મુજબ કિસ્સા કરીએ:
    \begin{enumerate}
    \item $x \in \FV{N}$ હોય તો:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]} &=
        \FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = ((\FV{N} \setminus \{x\}) \cup \{y\}) \setminus \{y\}
         && \text{\olref[sub]{thm:infv} મુજબ} \\
        & = \FV{N} \setminus \{x\} \\
        & = \FV{\lambd[x][N]}
      \end{align*}
    \item $x \notin \FV{N}$ હોય તો:
      \begin{align*}
        \FV{\lambd[y][\Subst{N}{y}{x}]}
        & = \FV{\Subst{N}{y}{x}} \setminus \{y\} \\
        & = \FV{N} \setminus \{x\}
         && \text{\olref[sub]{thm:notinfv} મુજબ} \\
        & = \FV{\lambd[x][N]}.
      \end{align*}
    \end{enumerate}
  \item બીજા ત્રણ કિસ્સા અભ્યાસપ્રશ્ન તરીકે છોડીએ છીએ.
  \end{enumerate}
\sourcecorrection{OLLAM-022}{સ્થિર અંગ્રેજી મૂળની આ
સાબિતીમાં~$x\in FV(N)$, $x\notin FV(N)$ અને
$FV\{\Subst{N}{y}{x}\}$ એમ ત્રણ જગ્યાએ મુક્ત-ચલ
સંકેતનું~$\backslash$ છૂટી ગયું છે. અહીં બધે~$\FV{}$
સંકેત વાપર્યો છે.}
\end{proof}

