\begin{defn}
  \ollabel{defn:Turing-Y}
  \emph{Y-સંયોજક} આ પદ છે:
  \[
  Y \ident (\lambd[ux][x(uux)])(\lambd[ux][x(uux)]).
  \]
\end{defn}

source_text:
\begin{thm}
  $Y$ has the property that $Yg \red g(Yg)$ for any term $g$. Thus,
  $Yg$ is always a fixpoint of~$g$.
\end{thm}

target_text:
\begin{thm}
  $Y$નો એવો ગુણધર્મ છે કે કોઈ પણ પદ~$g$ માટે
  $Yg \red g(Yg)$ છે. તેથી
  $Yg$ હંમેશા $g$નું સ્થિરબિંદુ છે.
\end{thm}

source_text:
\begin{proof}
  Let's abbreviate $(\lambd[ux][x(uux)])$ by~$U$, so that $Y \ident UU$. Then
  \begin{align*}
    Y g &\ident (\lambd[ux][x(uux)])U\,g \\
    &\red (\lambd[x][x(UUx)])g\\
    & \red g(UUg) \ident g(Yg).
  \end{align*}
  Since $g(Yg)$ and $Yg$ both reduce to $g(Yg)$, $g(Yg) \equal[\beta]
  Yg$, so $Yg$ is a fixpoint of~$g$.
\end{proof}

target_text:
\begin{proof}
  $(\lambd[ux][x(uux)])$ને સંક્ષેપમાં $U$ કહીએ; ત્યારે
  $Y \ident UU$. હવે
  \begin{align*}
    Y g &\ident (\lambd[ux][x(uux)])U\,g \\
    &\red (\lambd[x][x(UUx)])g\\
    & \red g(UUg) \ident g(Yg).
  \end{align*}
  $g(Yg)$ અને $Yg$ બંને $g(Yg)$માં લઘુકૃત થાય છે,
  તેથી $g(Yg) \equal[\beta] Yg$; આમ $Yg$ એ $g$નું
  સ્થિરબિંદુ છે.
\end{proof}

