\begin{defn}
  A \emph{propositional language} consists of a set $\Lang L$ of
  \emph{connectives}. Each connective $\star$ has an \emph{arity}; a
  connective of arity~$n$ is said to be \emph{$n$-place.}
  Connectives of arity~$0$ are also called \emph{constants};
  connectives of arity~$1$ are called \emph{unary}, and connectives of
  arity~$2$, \emph{binary}.
\end{defn}

target_text:
\begin{defn}
  \emph{વિધાનાત્મક ભાષા} એટલે સંયોજકોનો ગણ~$\Lang L$.
  દરેક સંયોજક~$\star$ની \emph{આર્ગ્યુમેન્ટ-સંખ્યા}
  હોય છે; આર્ગ્યુમેન્ટ-સંખ્યા~$n$ ધરાવતો સંયોજક
  \emph{$n$-સ્થાનીય} કહેવાય છે. આર્ગ્યુમેન્ટ-સંખ્યા~$0$
  ધરાવતા સંયોજકો \emph{અચલો} પણ કહેવાય છે;
  આર્ગ્યુમેન્ટ-સંખ્યા~$1$ ધરાવતાં સંયોજકોને
  \emph{એકસ્થાનીય} અને આર્ગ્યુમેન્ટ-સંખ્યા~$2$
  ધરાવતાંને \emph{દ્વિસ્થાનીય} કહે છે.
\end{defn}

source_text:
\begin{defn}[Matrix]
\ollabel{defn:matrix}
A \emph{matrix} for the logic~$\Log L$ consists of:
\begin{enumerate}
\item a set of connectives making up a language~$\Lang L$;
\item a set $V \neq \emptyset$ of truth values;
\item a set $V^+ \subseteq V$ of designated truth values;
\item for each $n$-place connective $\star$ in $\Lang L$, a truth
function~$\tf{\star} : V^n \to V$. If $n = 0$, then $\tf{\star}$ is
just an element of~$V$.
\end{enumerate}
\end{defn}

target_text:
\begin{defn}[શ્રેણિક]
\ollabel{defn:matrix}
તર્કશાસ્ત્ર~$\Log L$ માટેની \emph{શ્રેણિક}માં આ હોય છે:
\begin{enumerate}
\item ભાષા~$\Lang L$ બનાવતો સંયોજકોનો ગણ;
\item સત્યમૂલ્યોનો અરિક્ત ગણ~$V \neq \emptyset$;
\item નિર્દિષ્ટ સત્યમૂલ્યોનો ગણ~$V^+ \subseteq V$;
\item $\Lang L$ના દરેક $n$-સ્થાનીય સંયોજક~$\star$
માટે સત્યવિધેય~$\tf{\star} : V^n \to V$. જો
$n = 0$ હોય, તો $\tf{\star}$ એ $V$નો માત્ર એક ઘટક છે.
\end{enumerate}
\end{defn}

source_text:
\begin{ex}
The matrix for classical logic~\LogCL{} consists of:
\begin{enumerate}
  \item The standard propositional language $\Lang L_0$ with
  $\lfalse$, $\lnot$, $\land$, $\lor$, $\lif$.
  \item The set of truth values $V = \{\True, \False\}$.
  \item $\True$ is the only designated value, i.e., $V^+ = \{\True\}$.
  \item For $\lfalse$, we have $\tf{\lfalse} = \False$. The other
  truth functions are given by the usual truth tables (see
  \olref{fig:tf-CL}).
\end{enumerate}
\begin{figure}
  \begin{center}
      \begin{tabular}{c|c} 
        $\tf{\lnot}$ & \\ 
        \hline  
        $\True$ & $\False$ \\ 
        $\False$ & $\True$ 
      \end{tabular}
      \quad
      \begin{tabular}{c|cc} 
        $\tf{\land}$ & $\True$ & $\False$ \\ 
        \hline 
        $\True$ & $\True$ & $\False$ \\ 
        $\False$ & $\False$ & $\False$ 
      \end{tabular}
      \quad
      \begin{tabular}{c|cc} 
        $\tf{\lor}$ & $\True$ & $\False$ \\ 
        \hline 
        $\True$ & $\True$ & $\True$ \\ 
        $\False$ & $\True$ & $\False$ 
      \end{tabular}
      \quad
      \begin{tabular}{c|cc} 
        $\tf{\lif}$ & $\True$ & $\False$ \\ 
        \hline 
        $\True$ & $\True$ & $\False$ \\ 
        $\False$ & $\True$ & $\True$ 
      \end{tabular}
    \end{center} 
    \caption{Truth functions for classical logic~$\LogCL$.}
    \ollabel{fig:tf-CL}
  \end{figure}
  \end{ex}

