\begin{defn} 
\begin{enumerate}
\item !!^a{formula}~$!A$ is \emph{satisfiable} if for
  some~$\pAssign{v}$, $\pSat{v}{!A}$; it is
  \emph{unsatisfiable} if for no $\pAssign{v}$, $\pSat{v}{!A}$;
\item !!^a{formula}~$!A$ is a \emph{tautology} if $\pSat{v}{!A}$ for
  all !!{valuation}s~$v$;
\item If $\Gamma$ is a set of !!{formula}s, $\Gamma \Entails !A$ (``$\Gamma$
  entails $!A$'') if and only if $\pSat{v}{!A}$ for every
  !!{valuation}~$\pAssign{v}$ for which $\pSat{v}{\Gamma}$.
\item If $\Gamma$ is a set of !!{formula}s, $\Gamma$ is
  \emph{satisfiable} if there is !!a{valuation}~$\pAssign{v}$ for which
  $\pSat{v}{\Gamma}$, and $\Gamma$ is
  \emph{unsatisfiable} otherwise.
\end{enumerate} 
\end{defn}

target_text:
\begin{defn}
\begin{enumerate}
\item કોઈ~$\pAssign{v}$ માટે $\pSat{v}{!A}$ હોય, તો
  !!^a{formula}~$!A$ \emph{સંતોષ્ય} છે; કોઈ પણ $\pAssign{v}$ માટે
  $\pSat{v}{!A}$ ન હોય, તો તે \emph{અસંતોષ્ય} છે;
\item બધાં !!{valuation}s~$v$ માટે $\pSat{v}{!A}$ હોય, તો
  !!^a{formula}~$!A$ \emph{પુનરુક્તિ} છે;
\item જો $\Gamma$ એ !!{formula}sનો ગણ હોય, તો $\Gamma \Entails !A$
  (``$\Gamma$, $!A$ને ફલિત કરે છે'') ત્યારે અને માત્ર ત્યારે, જ્યારે
  $\pSat{v}{\Gamma}$ હોય એવા દરેક !!{valuation}~$\pAssign{v}$ માટે
  $\pSat{v}{!A}$ હોય.
\item જો $\Gamma$ એ !!{formula}sનો ગણ હોય, તો એવા કોઈ
  !!a{valuation}~$\pAssign{v}$ માટે $\pSat{v}{\Gamma}$ હોય ત્યારે
  $\Gamma$ \emph{સંતોષ્ય} છે; અન્યથા $\Gamma$ \emph{અસંતોષ્ય} છે.
\end{enumerate}
\end{defn}

source_text:
\begin{prop}
\ollabel{prop:semanticalfacts} 
\begin{enumerate} 
\item $!A$ is a tautology if and only if
  $\emptyset \Entails !A$; 
\item If $\Gamma$ is satisfiable then every finite subset of $\Gamma$
  is also satisfiable; 
\item\ollabel{def:monotonicity}%
Monotonicity: if $\Gamma \subseteq \Delta$
  and $\Gamma \Entails !A$ then also $\Delta \Entails !A$;
\item\ollabel{def:Cut}%
Transitivity: if $\Gamma \Entails !A$ and
  $\Delta \cup \{ !A\} \Entails !B$ then $\Gamma \cup \Delta \Entails
  !B$;
\end{enumerate}
\end{prop}

target_text:
\begin{prop}
\ollabel{prop:semanticalfacts}
\begin{enumerate}
\item $!A$ પુનરુક્તિ હોય ત્યારે અને માત્ર ત્યારે
  $\emptyset \Entails !A$;
\item જો $\Gamma$ સંતોષ્ય હોય, તો $\Gamma$નો દરેક સાન્ત ઉપગણ પણ
  સંતોષ્ય છે;
\item\ollabel{def:monotonicity}%
એકદિશવર્ધિતા: જો $\Gamma \subseteq \Delta$
  અને $\Gamma \Entails !A$, તો $\Delta \Entails !A$ પણ;
\item\ollabel{def:Cut}%
પરંપરિતતા: જો $\Gamma \Entails !A$ અને
  $\Delta \cup \{ !A\} \Entails !B$, તો $\Gamma \cup \Delta \Entails
  !B$;
\end{enumerate}
\end{prop}

