\begin{prob}
  Give truth tables to show that the following are tautologies
  of~$\LogGod[3]$:
  \begin{align*}
    & \lnot\lnot p \lor \lnot p\\
    & (p \lif q) \lor (q \lif p) \\
    & \lnot(p \land q) \lif (\lnot p \lor \lnot q) \\
    & (p \lif q) \lor (q \lif r) \lor (r \lif s)
  \end{align*}
\end{prob}

target_text:
\begin{prob}
  નીચેનાં સૂત્રો~$\LogGod[3]$માં પુનરુક્તિ છે તે બતાવવા
  સત્યતાસારણીઓ આપો:
  \begin{align*}
    & \lnot\lnot p \lor \lnot p\\
    & (p \lif q) \lor (q \lif p) \\
    & \lnot(p \land q) \lif (\lnot p \lor \lnot q) \\
    & (p \lif q) \lor (q \lif r) \lor (r \lif s)
  \end{align*}
\end{prob}

