\begin{proof}
  This can be seen by comparing the truth tables for the connectives
  given in \olref[thr][luk]{def:lukasiewicz} with the truth tables
  determined by the equations in \olref{def:lukasiewicz}:
  \begin{center}
    \begin{tabular}{c|c} 
      $\tf{\lnot}$ & \\ 
      \hline  
      $1$ & $0$ \\ 
      $1/2$ & $1/2$ \\
      $0$ & $1$ 
    \end{tabular}
    \quad
    \begin{tabular}{c|ccc} 
      $\tf{\land}[\LogLuk[3]]$ & $1$ & $1/2$ & $0$ \\ 
      \hline 
      $1$ & $1$ & $1/2$ & $0$ \\ 
      $1/2$ & $1/2$ & $1/2$ & $0$\\ 
      $0$ & $0$ & $0$ & $0$ 
    \end{tabular}
    \\[2ex]
    \begin{tabular}{c|ccc} 
      $\tf{\lor}[\LogLuk[3]]$ & $1$ & $1/2$ & $0$ \\ 
      \hline 
      $1$ & $1$ & $1$ & $1$ \\ 
      $1/2$ & $1$ & $1/2$ & $1/2$ \\
      $0$ & $1$ & $1/2$ & $0$ 
    \end{tabular}
    \quad
    \begin{tabular}{c|ccc} 
      $\tf{\lif}[\LogLuk[3]]$ & $1$ & $1/2$ & $0$ \\ 
      \hline 
      $1$ & $1$ & $1/2$ & $0$ \\ 
      $1/2$ & $1$ & $1$ & $1/2$  \\ 
      $0$ & $1$ & $1$ & $1$ 
    \end{tabular}
  \end{center} 
\end{proof}

