\begin{prop}\ollabel{prop:god-infty-m}
  If $\Gamma \Entails[\LogGod[\infty]] !B$ then $\Gamma
  \Entails[\LogGod[m]] !B$ for all~$m \ge 2$.
\end{prop}

target_text:
