source_text:
\begin{prob}
  Show that $(p \lif q) \lor (q \lif p)$ is a
  tautology of~$\LogGod[\infty]$.
\end{prob}

target_text:
\begin{prob}
  $(p \lif q) \lor (q \lif p)$ એ~$\LogGod[\infty]$ની
  પુનરુક્તિ છે તે બતાવો.
\end{prob}

source_text:
\begin{prob}
  Show that $(p \lif q) \lor (q \lif r) \lor (r \lif s)$, which is 
  a tautology of $\LogGod[3]$, is not a tautology of~$\LogGod[\infty]$.
\end{prob}

target_text:
\begin{prob}
  $(p \lif q) \lor (q \lif r) \lor (r \lif s)$ એ
  $\LogGod[3]$ની પુનરુક્તિ છે, પરંતુ~$\LogGod[\infty]$ની
  પુનરુક્તિ નથી, તે બતાવો.
\end{prob}

