source_text:
\begin{prob}
  Let $\mModel{M} = \tuple{W, R, V}$ be a model, and suppose $w_1, w_2 \in
  W$ are such that:
  \begin{enumerate}
  \item $w_1 \in V(p)$ if and only if $w_2 \in V(p)$ (for every !!{propositional variable} $p$); and
  \item for all $w \in W$: $Rw_1w$ if and only if $Rw_2w$.
  \end{enumerate}
  Using induction on !!{formula}s, show that for all !!{formula}s $!A$:
  $\mSat{M}{!A}[w_1]$ if and only if $\mSat{M}{!A}[w_2]$.
\end{prob}

target_text:
\begin{prob}
  માનો કે $\mModel{M} = \tuple{W, R, V}$ નિદર્શન છે
  અને $w_1, w_2 \in W$ માટે નીચેની શરતો છે:
  \begin{enumerate}
  \item $w_1 \in V(p)$ જો અને માત્ર જો $w_2 \in V(p)$
    (દરેક !!{propositional variable} $p$ માટે); અને
  \item બધા $w \in W$ માટે: $Rw_1w$ જો અને માત્ર જો $Rw_2w$.
  \end{enumerate}
  !!{formula}s પર અનુમાન વડે બતાવો કે બધા !!{formula}s $!A$ માટે:
  $\mSat{M}{!A}[w_1]$ જો અને માત્ર જો $\mSat{M}{!A}[w_2]$.
\end{prob}

