source_text:
\begin{defn}
  !!^a{formula}~$!A$ is \emph{true in a model} $M = \tuple{W, R,
    V}$, written $\mSat{M}{!A}$, if and only if $\mSat{M}{!A}[w]$
  for every $w \in W$.
\end{defn}

target_text:
\begin{defn}
  !!^a{formula}~$!A$ એ નિદર્શન $M = \tuple{W, R,
    V}$માં \emph{સત્ય} છે, જે $\mSat{M}{!A}$થી દર્શાવાય છે,
  ત્યારે અને માત્ર ત્યારે જ જ્યારે દરેક $w \in W$ માટે
  $\mSat{M}{!A}[w]$ હોય.
\end{defn}

source_text:
\begin{prop}\ollabel{prop:truthfacts}
  \begin{enumerate}
  \item If $\mSat{M}{!A}$ then $\mSat/{M}{\lnot !A}$, but \emph{not}
    vice-versa.
  \item If $\mSat{M}{!A \lif !B}$ then $\mSat{M}{!A}$ only if
    $\mSat{M}{!B}$, but \emph{not} vice-versa.
  \end{enumerate}
\end{prop}

target_text:
\begin{prop}\ollabel{prop:truthfacts}
  \begin{enumerate}
  \item જો $\mSat{M}{!A}$ હોય તો $\mSat/{M}{\lnot !A}$ હોય,
    પણ તેનું વિપરીત વિધાન \emph{સાચું નથી}.
  \item જો $\mSat{M}{!A \lif !B}$ હોય તો $\mSat{M}{!A}$ હોય
    ત્યારે $\mSat{M}{!B}$ પણ હોય; પરંતુ તેનું વિપરીત વિધાન
    \emph{સાચું નથી}.
  \end{enumerate}
\end{prop}

source_text:
\begin{proof}
  \begin{enumerate}
  \item If $\mSat{M}{!A}$ then $!A$ is true at all worlds in $W$, and
    since $W \neq \emptyset$, it can't be that $\mSat{M}{\lnot!A}$, or
    else $!A$ would have to be both true and false at some
    world.

target_text:
\begin{proof}
  \begin{enumerate}
  \item જો $\mSat{M}{!A}$ હોય તો $!A$ એ $W$ના બધા જગતોમાં
    સત્ય છે. $W \neq \emptyset$ હોવાથી $\mSat{M}{\lnot!A}$
    શક્ય નથી; નહીંતર કોઈ એક જગતમાં $!A$ સત્ય પણ અને અસત્ય પણ
    હોવું પડે.

source_text:
\begin{prob}
  Consider the following model $\mModel{M}$ for the language
  comprising $p_1$, $p_2$, $p_3$ as the only !!{propositional variable}s:
  \begin{center}
    \begin{tikzpicture}[modal]
      \node[world] (w1) [label={[align=right]left:\mTrue{p_1}\\\mFalse{p_2}\\\mFalse{p_3}}]
            {$w_1$} ; 
      \node[world] (w2) [label={[align=right]right:\mTrue{p_1}\\\mTrue{p_2}\\\mFalse{p_3}},
        below right=of w1]  {$w_2$}; 
      \node[world] (w3) [label={[align=right]right:\mTrue{p_1}\\\mTrue{p_2}\\\mTrue{p_3}},
        above right=of w2] {$w_3$};
      \draw[reflexive above] (w3) to (w3); 
      \draw[->] (w1) to (w2);
      \draw[->] (w2) to (w3);
      \draw[->] (w1) to (w3); 
    \end{tikzpicture}
  \end{center}
  Are the following !!{formula}s and schemas true in the model $\mModel{M}$,
  i.e., true at every world in $\mModel{M}$? Explain.
  \begin{enumerate}
  \item $p\lif \Diamond p$ (for $p$ atomic);
  \item $!A\lif \Diamond !A$ (for $!A$ arbitrary);
  \item $\Box p \lif p$ (for $p$ atomic);
  \item $\lnot p \lif \Diamond \Box p$ (for $p$ atomic);
  \item $\Diamond \Box !A$ (for $!A$ arbitrary);
  \item $\Box \Diamond p$ (for $p$ atomic). 
  \end{enumerate}
\end{prob}

target_text:
\begin{prob}
  માત્ર $p_1$, $p_2$, $p_3$ને !!{propositional variable}s તરીકે
  ધરાવતી ભાષા માટે નીચેનું નિદર્શન $\mModel{M}$ વિચારો:
  \begin{center}
    \begin{tikzpicture}[modal]
      \node[world] (w1) [label={[align=right]left:\mTrue{p_1}\\\mFalse{p_2}\\\mFalse{p_3}}]
            {$w_1$} ; 
      \node[world] (w2) [label={[align=right]right:\mTrue{p_1}\\\mTrue{p_2}\\\mFalse{p_3}},
        below right=of w1]  {$w_2$}; 
      \node[world] (w3) [label={[align=right]right:\mTrue{p_1}\\\mTrue{p_2}\\\mTrue{p_3}},
        above right=of w2] {$w_3$};
      \draw[reflexive above] (w3) to (w3); 
      \draw[->] (w1) to (w2);
      \draw[->] (w2) to (w3);
      \draw[->] (w1) to (w3); 
    \end{tikzpicture}
  \end{center}
  નીચેના !!{formula}s અને સૂત્ર-ઢાંચા નિદર્શન
  $\mModel{M}$માં, એટલે કે $\mModel{M}$ના દરેક જગતમાં, સત્ય છે?
  સમજાવો.
  \begin{enumerate}
  \item $p\lif \Diamond p$ ($p$ પરમાણુ હોય ત્યારે);
  \item $!A\lif \Diamond !A$ ($!A$ કોઈપણ સૂત્ર હોય ત્યારે);
  \item $\Box p \lif p$ ($p$ પરમાણુ હોય ત્યારે);
  \item $\lnot p \lif \Diamond \Box p$ ($p$ પરમાણુ હોય ત્યારે);
  \item $\Diamond \Box !A$ ($!A$ કોઈપણ સૂત્ર હોય ત્યારે);
  \item $\Box \Diamond p$ ($p$ પરમાણુ હોય ત્યારે).
  \end{enumerate}
\end{prob}

\begin{defn}
  !!^a{formula}~$!A$ નિદર્શનોના વર્ગ $\mClass{C}$માં
  \emph{માન્ય} છે, જો તે $\mClass{C}$ના દરેક નિદર્શનમાં
  સત્ય હોય (એટલે કે $\mClass{C}$ના દરેક નિદર્શનના
  દરેક જગતમાં સત્ય હોય). જો $!A$ એ~$\mClass{C}$માં
  માન્ય હોય, તો $\mClass{C} \Entails !A$ લખીએ;
  અને $!A$ \emph{બધાં} નિદર્શનોના વર્ગમાં માન્ય હોય,
  તો $\Entails !A$ લખીએ.
\end{defn}

source_text:
\begin{prop}\ollabel{prop:subset-class}
  If $!A$ is valid in $\mClass{C}$ it is also valid in each class
  $\mClass{C}' \subseteq \mClass{C}$.
\end{prop}

target_text:
\begin{prop}\ollabel{prop:subset-class}
  જો $!A$ વર્ગ $\mClass{C}$માં માન્ય હોય, તો તે દરેક
  ઉપવર્ગ $\mClass{C}' \subseteq \mClass{C}$માં પણ માન્ય છે.
\end{prop}

source_text:
\begin{prop}\ollabel{prop:Nec-rule}
  If $!A$ is valid, then so is $\Box!A$. 
\end{prop}

target_text:
\begin{prop}\ollabel{prop:Nec-rule}
  જો $!A$ માન્ય હોય, તો $\Box!A$ પણ માન્ય છે.
\end{prop}

\begin{proof}
  $\Entails !A$ માનો. $\Entails \Box!A$ બતાવવા માટે
  કોઈપણ નિદર્શન $\mModel{M} =
  \tuple{W, R, V}$ અને $w \in W$ લો. જો $Rww'$ હોય,
  તો $!A$ માન્ય હોવાથી $\mSat{M}{!A}[w']$ છે;
  તેથી $\mSat{M}{\Box!A}[w]$ પણ છે. નિદર્શન
  $\mModel{M}$ અને જગત $w$ ગમે તે હતાં, તેથી
  $\Entails \Box!A$.
\end{proof}

source_text:
\begin{prob}
  Show that the following are valid:
  \begin{enumerate}
  \item $\Box p \lif \Box (q \lif p)$;
  \item $\Box \lnot \lfalse$;
  \item $\Box p \lif (\Box q \lif \Box p)$.
  \end{enumerate}
\end{prob}

