\begin{defn}
  મોડલ !!{formula}~$!B$ \emph{પુનરુક્તિનો પ્રતિસ્થાપન દૃષ્ટાંત}
  ત્યારે અને માત્ર ત્યારે જ છે જ્યારે !!{propositional
    variable}s $p_1$, \dots,~$p_n$ ધરાવતી મોડલ-મુક્ત
  પુનરુક્તિ~$!A$ અને !!{formula}s $!D_1$,
  \dots,~$!D_n$ એવાં હોય કે $!B \ident \SSubst{!A}{\subst{!D_1}{p_1},
    \dots, \subst{!D_n}{p_n}}$.
\end{defn}

