source_text:
With this definition, it will turn out that the set of !!{derivable}
formulas forms a normal modal logic, and that any !!{derivable}
!!{formula} is true in every model in which every axiom is true. This
property of !!{derivation}s is called \emph{soundness}. The converse,
\emph{completeness}, is harder to prove.

\begin{defn}
  A \emph{modal logic} is a set~$\Sigma$ of modal !!{formula}s which
  \begin{enumerate}
  \item contains all tautologies, and
  \item is closed under substitution, i.e., if $!A \in \Sigma$, and
    $!D_1$, \dots, $!D_n$ are !!{formula}s, then
    \[
    \SSubst{!A}{\subst{!D_1}{p_1}, \dots, \subst{!D_n}{p_n}} \in \Sigma,
    \]
    \item is closed under \emph{modus ponens}, i.e., if $!A$ and $!A
      \lif !B \in \Sigma$, then $!B \in \Sigma$.
  \end{enumerate}
\end{defn}

target_text:
\begin{defn}
  \emph{મોડલ તર્કશાસ્ત્ર} એ મોડલ !!{formula}sનો એવો ગણ~$\Sigma$ છે જે
  \begin{enumerate}
  \item બધી પુનરુક્તિઓ ધરાવે છે, અને
  \item પ્રતિસ્થાપન હેઠળ બંધ છે, એટલે કે જો $!A \in \Sigma$ હોય અને
    $!D_1$, \dots, $!D_n$ !!{formula}s હોય, તો
    \[
    \SSubst{!A}{\subst{!D_1}{p_1}, \dots, \subst{!D_n}{p_n}} \in \Sigma,
    \]
    \item \emph{મોડસ પોનેન્સ} હેઠળ બંધ છે, એટલે કે જો $!A$ અને $!A
      \lif !B \in \Sigma$ હોય, તો $!B \in \Sigma$ હોય છે.
  \end{enumerate}
\end{defn}

source_text:
\begin{defn}
  A modal logic $\Sigma$ is \emph{normal} if it contains
  \begin{align*}
    \tag{\Ax{K}} & \Box(p \lif q) \lif (\Box p \lif \Box q),
    \iftag{prvDiamond}{\\
      \tag{\Dual} & \Diamond p \liff \lnot\Box\lnot p}{}
  \end{align*}
  and is closed under \emph{necessitation}, i.e., if $!A \in
  \Sigma$, then $\Box !A \in \Sigma$.
\end{defn}

target_text:
\begin{defn}
  મોડલ તર્ક $\Sigma$ \emph{સામાન્ય} છે, જો તે આ સૂત્રો ધરાવે:
  \begin{align*}
    \tag{\Ax{K}} & \Box(p \lif q) \lif (\Box p \lif \Box q),
    \iftag{prvDiamond}{\\
      \tag{\Dual} & \Diamond p \liff \lnot\Box\lnot p}{}
  \end{align*}
  અને તે \emph{આવશ્યકીકરણ} હેઠળ બંધ હોય, એટલે કે $!A \in
  \Sigma$ હોય, તો $\Box !A \in \Sigma$ પણ હોય.
\end{defn}

