\begin{prop}
  $\Log{K} \Proves \Box!A \lif \Box (!B\lif !A)$
\end{prop}

target_text:
\begin{prop}
  $\Log{K} \Proves \Box!A \lif \Box (!B\lif !A)$
\end{prop}

source_text:
\begin{proof}
  \begin{derivation}
    1. & $!A \lif (!B \lif !A)$ & \Taut \\
    2. & $\Box(!A \lif (!B \lif !A))$ & \Nec, 1 \\
    3. & $\Box(!A \lif (!B \lif !A)) \lif
    (\Box!A \lif \Box(!B \lif !A))$ & \Ax{K}\\
    4. & $\Box!A \lif \Box (!B\lif !A)$ & \MP, 2, 3
  \end{derivation}
\end{proof}

target_text:
\begin{proof}
  \begin{derivation}
    1. & $!A \lif (!B \lif !A)$ & \Taut \\
    2. & $\Box(!A \lif (!B \lif !A))$ & \Nec, 1 \\
    3. & $\Box(!A \lif (!B \lif !A)) \lif
    (\Box!A \lif \Box(!B \lif !A))$ & \Ax{K}\\
    4. & $\Box!A \lif \Box (!B\lif !A)$ & \MP, 2, 3
  \end{derivation}
\end{proof}

