source_text:
\begin{prop}
  $\Log{K} \Proves \lnot\Box p \lif \Diamond \lnot p$
\end{prop}

target_text:
\begin{prop}
  $\Log{K} \Proves \lnot\Box p \lif \Diamond \lnot p$
\end{prop}

source_text:
\begin{proof}
  \iftag{prvDiamond}{% Diamond is primitive
  \begin{derivation}
    1. & $\Log{K} \Proves \Diamond \lnot p \liff \lnot\Box\lnot\lnot p$ &
    \Dual\\
    2. & $\Log{K} \Proves \lnot \Box \lnot\lnot p \lif \Diamond \lnot p$ & \PL, 1\\
    3. & $\Log{K} \Proves \lnot\Box p \lif \Diamond \lnot p$ & $p$ for $\lnot\lnot p$\\
  \end{derivation}
  }{% Diamond is defined
  \begin{derivation}
    1. & $\Log{K} \Proves \lnot \Box \lnot\lnot p \lif \Diamond \lnot p$ & \Taut\\
    2. & $\Log{K} \Proves \lnot\Box p \lif \Diamond \lnot p$ & $p$ for $\lnot\lnot p$\\
  \end{derivation}
  The formula on line~$1$ is an instance of $\lnot q \lif \lnot q$,
  substituting $\Box\lnot\lnot p$ for~$q$. $\Diamond\lnot p$ and
  $\lnot\Box\lnot\lnot p$ are identical, since $\Diamond$ is defined
  as~$\lnot\Box\lnot$.}
\end{proof}

target_text:
\begin{proof}
  \iftag{prvDiamond}{% Diamond મૂળભૂત છે
  \begin{derivation}
    1. & $\Log{K} \Proves \Diamond \lnot p \liff \lnot\Box\lnot\lnot p$ &
    \Dual\\
    2. & $\Log{K} \Proves \lnot \Box \lnot\lnot p \lif \Diamond \lnot p$ & \PL, 1\\
    3. & $\Log{K} \Proves \lnot\Box p \lif \Diamond \lnot p$ & $\lnot\lnot p$ના સ્થાને $p$\\
  \end{derivation}
  }{% Diamond વ્યાખ્યાયિત છે
  \begin{derivation}
    1. & $\Log{K} \Proves \lnot \Box \lnot\lnot p \lif \Diamond \lnot p$ & \Taut\\
    2. & $\Log{K} \Proves \lnot\Box p \lif \Diamond \lnot p$ & $\lnot\lnot p$ના સ્થાને $p$\\
  \end{derivation}
  પંક્તિ~$1$ પરનું સૂત્ર $\lnot q \lif \lnot q$નો દૃષ્ટાંત છે, જેમાં
  $q$ના સ્થાને $\Box\lnot\lnot p$ મૂક્યું છે. $\Diamond\lnot p$ અને
  $\lnot\Box\lnot\lnot p$ એક જ સૂત્ર છે, કારણ કે $\Diamond$ની
  વ્યાખ્યા~$\lnot\Box\lnot$ છે.}
\end{proof}

source_text:
\begin{prop}
  If $!A$ is a substitution instance of $!B$ and $\Log{K} \Proves !B$,
  then $\Log{K} \Proves !A$.
\end{prop}

target_text:
\begin{prop}
  જો $!A$ એ $!B$નો પ્રતિસ્થાપન દૃષ્ટાંત હોય અને $\Log{K} \Proves !B$,
  તો $\Log{K} \Proves !A$.
\end{prop}

source_text:
\begin{proof}
  It is tedious but routine to verify (by induction on the length of
  the !!{derivation} of~$!B$) that applying a substitution to an
  entire !!{derivation} also results in a correct
  !!{derivation}. Specifically, substitution instances of tautological
  instances are themselves tautological instances, substitution
  instances of instances of~\iftag{prvDiamond}{\Dual{} and~}{}\Ax{K}
  are themselves instances of~\iftag{prvDiamond}{\Dual{}
    and~}{}\Ax{K}, and applications of \MP{} and~\Nec{} remain correct
  when substituting !!{formula}s for !!{propositional variable}s in
  both premise(s) and conclusion.
\end{proof}

target_text:
\begin{proof}
  આખી !!{derivation}માં પ્રતિસ્થાપન કરતાં પણ યોગ્ય !!{derivation}
  મળે છે તે ચકાસવું લાંબું, પરંતુ નિયમિત કામ છે ($!B$ની
  !!{derivation}ની લંબાઈ પર આગમન કરો). ખાસ કરીને, પુનરુક્તિના
  દૃષ્ટાંતોના પ્રતિસ્થાપન દૃષ્ટાંતો પોતે પુનરુક્તિના દૃષ્ટાંતો છે;
  \iftag{prvDiamond}{\Dual{} અને~}{}\Ax{K}ના દૃષ્ટાંતોના પ્રતિસ્થાપન
  દૃષ્ટાંતો પોતે~\iftag{prvDiamond}{\Dual{}
    અને~}{}\Ax{K}ના દૃષ્ટાંતો છે; અને પૂર્વપક્ષ(ઓ) તથા નિષ્કર્ષમાં
  !!{propositional variable}sના સ્થાને !!{formula}s મૂકતાં \MP{} અને~\Nec{}
  નો ઉપયોગ યોગ્ય જ રહે છે.
\end{proof}

source_text:
\begin{prop}
  $\Log{K} \Proves \Box (!A \lif !B) \lif (\Diamond !A \lif \Diamond
  !B)$
\end{prop}

target_text:
\begin{prop}
  $\Log{K} \Proves \Box (!A \lif !B) \lif (\Diamond !A \lif \Diamond
  !B)$
\end{prop}

source_text:
\begin{proof}
\begin{derivation}
