source_text:
\begin{lem}\ollabel{lem:box2}
  If $\Box^{-1} \Gamma \Proves[\Sigma] !A$ then $\Gamma
  \Proves[\Sigma] \Box!A$.
\end{lem}

target_text:
\begin{lem}\ollabel{lem:box2}
  જો $\Box^{-1} \Gamma \Proves[\Sigma] !A$ હોય, તો $\Gamma
  \Proves[\Sigma] \Box!A$.
\end{lem}

source_text:
\begin{proof}
  Suppose $\Box^{-1}\Gamma \Proves[\Sigma] !A$; then by
  \olref{lem:box1}, $\Box\Box^{-1}\Gamma \Proves \Box!A$. But since
  $\Box\Box^{-1}\Gamma \subseteq \Gamma$, also $\Gamma \Proves[\Sigma]
  \Box!A$ by monotonicity.
\end{proof}

target_text:
\begin{proof}
  ધારો કે $\Box^{-1}\Gamma \Proves[\Sigma] !A$; ત્યારે
  \olref{lem:box1} મુજબ $\Box\Box^{-1}\Gamma \Proves \Box!A$.
  પરંતુ $\Box\Box^{-1}\Gamma \subseteq \Gamma$ હોવાથી
  એકદિશવર્ધિતાથી $\Gamma \Proves[\Sigma] \Box!A$ પણ મળે છે.
\end{proof}

