\begin{prop}\ollabel{prop:box}
  If $\Gamma$ is complete $\Sigma$-consistent, then $\Box !A \in
  \Gamma$ if and only if for every complete $\Sigma$-consistent
  $\Delta$ such that $\Box^{-1} \Gamma \subseteq \Delta$, it holds
  that $!A \in \Delta$.
\end{prop}

