\begin{thm}\ollabel{thm:filtrations}
  If $\mModel{M^*}$ is a filtration of $\mModel{M}$ through $\Gamma$,
  then for every $!A \in \Gamma$ and $w \in W$, we have
  $\mSat{M}{!A}[w]$ if and only if $\mSat{M^*}{!A}[{[w]}]$.
\end{thm}

