\begin{defn}
  Where $\Gamma$ is closed under subformulas, the \emph{finest}
  filtration $\mModel{M^*}$ of a model $\mModel{M}$ is defined by putting:
  \[
  R^*[u][v] \quad \text{if and only if} \quad \exists u'\in [u] \;
  \exists v' \in [v] : Ru'v'.
  \]
\end{defn}

target_text:
\begin{defn}
  $\Gamma$ ઉપસૂત્રો હેઠળ બંધ હોય ત્યારે નિદર્શન $\mModel{M}$નું
  \emph{સૌથી સૂક્ષ્મ} ફિલ્ટ્રેશન $\mModel{M^*}$ આ રીતે વ્યાખ્યાયિત
  થાય છે:
  \[
  R^*[u][v] \quad \text{જો અને માત્ર જો} \quad \exists u'\in [u] \;
  \exists v' \in [v] : Ru'v'.
  \]
\end{defn}

