source_text:
\begin{prob}
  Find closed !!{tableau}s in~$\Log{K}$ for the following !!{formula}s:
  \begin{enumerate}
    \item $\Box \lnot p \lif \Box(p \lif q)$
    \item $(\Box p \lor \Box q) \lif \Box(p \lor q)$
    \item $\Diamond p \lif \Diamond(p \lor q)$
    \item $\Box(p \land q) \lif \Box p$
  \end{enumerate}
\end{prob}

target_text:
\begin{prob}
  નીચેના !!{formula}s માટે~$\Log{K}$માં બંધ !!{tableau}s શોધો:
  \begin{enumerate}
    \item $\Box \lnot p \lif \Box(p \lif q)$
    \item $(\Box p \lor \Box q) \lif \Box(p \lor q)$
    \item $\Diamond p \lif \Diamond(p \lor q)$
    \item $\Box(p \land q) \lif \Box p$
  \end{enumerate}
\end{prob}

source_text:
Relative to an interpretation of prefixes~$P$ we can define:
  \begin{enumerate}
  \item $\mModel{M}$ satisfies $\sFmla{\True}{!A}[\sigma]$ iff
    $\mSat{M}{!A}[f(\sigma)]$.
  \item $\mModel{M}$ satisfies $\sFmla{\False}{!A}[\sigma]$ iff
    $\mSat/{M}{!A}[f(\sigma)]$.
  \end{enumerate}
\end{defn}

target_text:
ઉપસર્ગો~$P$ના અર્થઘટનને અનુલક્ષીને વ્યાખ્યાયિત કરીએ છીએ:
  \begin{enumerate}
  \item $\mModel{M}$ એ $\sFmla{\True}{!A}[\sigma]$ને સંતોષે છે
    જો અને માત્ર જો
    $\mSat{M}{!A}[f(\sigma)]$.
  \item $\mModel{M}$ એ $\sFmla{\False}{!A}[\sigma]$ને સંતોષે છે
    જો અને માત્ર જો
    $\mSat/{M}{!A}[f(\sigma)]$.
  \end{enumerate}
\end{defn}

source_text:
\begin{prop}
  If $\Gamma$ contains both $\sFmla{\True}{!A}[\sigma]$ and
  $\sFmla{\False}{!A}[\sigma]$, for some !!{formula}~$!A$ and
  prefix~$\sigma$, then $\Gamma$ is unsatisfiable.
\end{prop}

target_text:
\begin{prop}
  જો $\Gamma$માં $\sFmla{\True}{!A}[\sigma]$ અને
  $\sFmla{\False}{!A}[\sigma]$ બંને હોય, કોઈ !!{formula}~$!A$
  અને ઉપસર્ગ~$\sigma$ માટે, તો $\Gamma$ અસંતોષ્ય છે.
\end{prop}

source_text:
\begin{proof}
  There cannot be a model~$\mModel{M}$ and interpretation~$f$ of
  $P(\Gamma)$ such that both $\mSat{M}{!A}[f(\sigma)]$ and
  $\mSat/{M}{!A}[f(\sigma)]$.
\end{proof}

target_text:
\begin{proof}
  એવું નિદર્શન~$\mModel{M}$ અને $P(\Gamma)$નું અર્થઘટન~$f$
  હોઈ શકે નહિ કે $\mSat{M}{!A}[f(\sigma)]$ અને
  $\mSat/{M}{!A}[f(\sigma)]$ બંને હોય.
\end{proof}

source_text:
\begin{thm}[Soundness]
  \ollabel{thm:tableau-soundness}
  If $\Gamma$ has a closed !!{tableau}, $\Gamma$ is unsatisfiable.
\end{thm}

target_text:
\begin{thm}[યથાર્થતા]
  \ollabel{thm:tableau-soundness}
  જો $\Gamma$ માટે બંધ !!{tableau} હોય, તો $\Gamma$ અસંતોષ્ય છે.
\end{thm}

source_text:
\begin{proof}
We call a branch of !!a{tableau} satisfiable iff the set of
!!{signed formula}s on it is satisfiable, and let's call !!a{tableau}
satisfiable if it contains at least one satisfiable branch.

Since $\mSat/{M}{\Box !B}[f(\sigma)]$, there is a $w \in W$ such that
  $Rf(\sigma)w$ and $\mSat/{M}{!B}[w]$. Let $f'$ be like $f$, except
  that $f'(\sigma.n) = w$. Since $f'(\sigma) = f(\sigma)$ and
  $Rf(\sigma)w$, we have $Rf'(\sigma)f'(\sigma.n)$, so $f'$ is an
  interpretation of $P(\Gamma) \cup \{\sigma.n\}$.  Obviously
  $\mSat/{M}{!B}[f'(\sigma.n)]$. Since $f(\sigma') = f'(\sigma')$ for
  all prefixes $\sigma' \in P(\Gamma)$, $\mSat{M}{\Gamma}[f']$.  So,
  $\mModel{M}, f'$ satisfies $\Gamma \cup
  \{\sFmla{\False}{!B}[\sigma.n]\}$.}
  }{}

target_text:
$\mSat/{M}{\Box !B}[f(\sigma)]$ હોવાથી એવું $w \in W$ છે કે
  $Rf(\sigma)w$ અને $\mSat/{M}{!B}[w]$. $f'$ એ $f$ જેવું જ
  રાખો, માત્ર $f'(\sigma.n) = w$. $f'(\sigma) = f(\sigma)$
  અને $Rf(\sigma)w$ હોવાથી $Rf'(\sigma)f'(\sigma.n)$;
  તેથી $f'$ એ $P(\Gamma) \cup \{\sigma.n\}$નું અર્થઘટન છે.
  સ્પષ્ટ છે કે $\mSat/{M}{!B}[f'(\sigma.n)]$.
  બધા ઉપસર્ગ $\sigma' \in P(\Gamma)$ માટે
  $f(\sigma') = f'(\sigma')$ હોવાથી $\mSat{M}{\Gamma}[f']$.
  આમ $\mModel{M}, f'$ એ $\Gamma \cup
  \{\sFmla{\False}{!B}[\sigma.n]\}$ને સંતોષે છે.}
  }{}

