source_text:
\begin{cor}
\ollabel{cor:entailment-soundness}
If $\Gamma \Proves !A$ then $\Gamma \Entails !A$.
\end{cor}

target_text:
\begin{cor}
\ollabel{cor:entailment-soundness}
જો $\Gamma \Proves !A$ હોય, તો $\Gamma \Entails !A$.
\end{cor}

source_text:
\begin{cor}
\ollabel{cor:weak-soundness}
If $\Proves !A$ then $!A$ is true in all models.
\end{cor}

target_text:
\begin{cor}
\ollabel{cor:weak-soundness}
જો $\Proves !A$ હોય, તો $!A$ બધાં નિદર્શનોમાં સત્ય છે.
\end{cor}

