source_text:
\begin{defn}
The basic language of temporal logic contains
\begin{enumerate}
  \tagitem{prvFalse}{The propositional constant for !!{falsity}~$\lfalse$.}{}
  \tagitem{prvTrue}{The propositional constant for !!{truth}~$\ltrue$.}{}
  \item A !!{denumerable}s set of !!{propositional variable}s: $\Obj
    p_0$, $\Obj p_1$, $\Obj p_2$, \dots
  \item The propositional connectives: \startycommalist
  \iftag{prvNot}{\ycomma $\lnot$ (negation)}{}%
  \iftag{prvAnd}{\ycomma $\land$ (conjunction)}{}%
  \iftag{prvOr}{\ycomma $\lor$ (disjunction)}{}%
  \iftag{prvIf}{\ycomma $\lif$ (!!{conditional})}{}%
  \iftag{prvIff}{\ycomma $\liff$ (!!{biconditional})}{}.
  \item Past operators $\Ptemp$ and $\Htemp$.
  \item Future operators $\Ftemp$ and $\Gtemp$.
\end{enumerate}
\end{defn}

target_text:
\begin{defn}
સમયસંબંધી તર્કની મૂળભૂત ભાષામાં નીચેની બાબતો હોય છે:
\begin{enumerate}
  \tagitem{prvFalse}{!!{falsity} માટેનો વિધાનાત્મક અચલાંક~$\lfalse$.}{}
  \tagitem{prvTrue}{!!{truth} માટેનો વિધાનાત્મક અચલાંક~$\ltrue$.}{}
  \item !!{propositional variable}sનો !!{denumerable}s ગણ: $\Obj
    p_0$, $\Obj p_1$, $\Obj p_2$, \dots
  \item વિધાનાત્મક સંયોજકો: \startycommalist
  \iftag{prvNot}{\ycomma $\lnot$ (નિષેધ)}{}%
  \iftag{prvAnd}{\ycomma $\land$ (સંયોજન)}{}%
  \iftag{prvOr}{\ycomma $\lor$ (વિયોજન)}{}%
  \iftag{prvIf}{\ycomma $\lif$ (!!{conditional})}{}%
  \iftag{prvIff}{\ycomma $\liff$ (!!{biconditional})}{}.
  \item ભૂતકાળના સંક્રિયકો $\Ptemp$ અને $\Htemp$.
  \item ભવિષ્યના સંક્રિયકો $\Ftemp$ અને $\Gtemp$.
\end{enumerate}
\end{defn}

source_text:
