  વ્યાખ્યાયિત થાય છે:
\begin{enumerate}
\tagitem{prvFalse}{$\lfalse$ પરમાણુક !!{formula} છે.}{}

source_text:
\tagitem{limitClause}{Nothing else is !!a{formula}.}{}
\end{enumerate}
\end{defn}

target_text:
