source_text:
\begin{defn}\ollabel{defn:since-until}
  \emph{Truth of !!a{formula}~$!A$ at~$t$} in a~$\mModel M$:
  \begin{enumerate}
  \item\ollabel{defn:sub:mmodels-since} \indcase{!A}{\Since  !B
    !C}{$\mSat{M}{\indfrm}[t]$ iff $\mSat{M}{!B}[t']$ for some $t' \in
    T$ with $t' \prec t$, and for all $s$ with $t' \prec s \prec t$,
    $\mSat{M}{!C}[s]$}
   \item\ollabel{defn:sub:mmodels-until} \indcase{!A}{\Until !B
    !C}{$\mSat{M}{\indfrm}[t]$ iff $\mSat{M}{!B}[t']$ for some $t' \in
    T$ with $t \prec t'$, and for all $s$ with $t \prec s \prec t'$,
    $\mSat{M}{!C}[s]$}
  \end{enumerate} 
\end{defn}

target_text:
\begin{defn}\ollabel{defn:since-until}
  નિદર્શ~$\mModel M$માં \emph{!!a{formula}~$!A$નું~$t$એ સત્ય હોવું}:
  \begin{enumerate}
  \item\ollabel{defn:sub:mmodels-since} \indcase{!A}{\Since  !B
    !C}{$\mSat{M}{\indfrm}[t]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે
    $t' \prec t$ ધરાવતા કોઈ $t' \in T$ માટે $\mSat{M}{!B}[t']$ હોય,
    અને $t' \prec s \prec t$ ધરાવતા દરેક $s$ માટે
    $\mSat{M}{!C}[s]$ હોય}
   \item\ollabel{defn:sub:mmodels-until} \indcase{!A}{\Until !B
    !C}{$\mSat{M}{\indfrm}[t]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે
    $t \prec t'$ ધરાવતા કોઈ $t' \in T$ માટે $\mSat{M}{!B}[t']$ હોય,
    અને $t \prec s \prec t'$ ધરાવતા દરેક $s$ માટે
    $\mSat{M}{!C}[s]$ હોય}
  \end{enumerate} 
\end{defn}

