\begin{defn}
  While the $\Knows$ operator is intended to symbolize individual
  knowledge, $\EKnows$, often read as ``everybody knows,'' symbolizes
  group knowledge. Where $G' \subseteq G$, we define $\EKnows_{G'} !A$
 as an abbreviation for \[\bigwedge_{b \in G'} \Knows_b !A.\]
\end{defn}

\begin{defn}
  A \emph{model} for the multi-agent epistemic language is a triple
  $\mModel{M} = \tuple{W, R, V}$, where
  \begin{enumerate}
  \item $W$ is a nonempty set of ``worlds,''
  \item For each $a \in G$, ${R}_a$ is a binary accessibility relation
  on~$W$, and
  \item $V$ is a function assigning to each !!{propositional
    variable}~$p$ a set $V(p)$ of possible worlds.
  \end{enumerate}
  When $R_a ww'$ holds, we say that $w'$ is \emph{accessible by a
    from}~$w$. When $w \in V(p)$ we say $p$ is \emph{true at}~$w$.
\end{defn}

\begin{defn}\ollabel{defn:mmodels}
  \emph{Truth of !!a{formula}~$!A$ at~$w$} in a~$\mModel M$, in symbols:
  $\mSat{M}{!A}[w]$, is defined inductively as follows:
  \begin{enumerate}
  \tagitem{prvFalse}{\indcase{!A}{\lfalse}{Never $\mSat{M}{\lfalse}[w]$}.}{}
  \tagitem{prvTrue}{\indcase{!A}{\ltrue}{Always $\mSat{M}{\ltrue}[w]$}.}{}
  \item $\mSat{M}{p}[w]$ iff $w \in V(p)$
  \tagitem{prvNot}{\indcase{!A}{\lnot !B}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat/{M}{!B}[w]$}.}{}
  \tagitem{prvAnd}{\indcase{!A}{(!B \land !C)}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w]$ and $\mSat{M}{!C}[w]$}.}{}
  \tagitem{prvOr}{\indcase{!A}{(!B \lor !C)}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w]$ or $\mSat{M}{!C}[w]$} (or both).}{}
  \tagitem{prvIf}{\indcase{!A}{(!B \lif !C)}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat/{M}{!B}[w]$ or $\mSat{M}{!C}[w]$}.}{}
  \tagitem{prvIff}{\indcase{!A}{(!B \liff !C)}{$\mSat{M}{\indfrm}[w]$ iff
    either both $\mSat{M}{!B}[w]$ and $\mSat{M}{!C}[w]$ or
    neither $\mSat{M}{!B}[w]$ nor $\mSat{M}{!C}[w]$}.}{}
  \item\ollabel{defn:sub:mmodels-box}
    \indcase{!A}{\Knows_a !B}{$\mSat{M}{\indfrm}[w]$ iff
    $\mSat{M}{!B}[w']$ for all $w' \in W$ with $R_a ww'$}
  \end{enumerate} 
\end{defn}

target_text:
\begin{defn}\ollabel{defn:mmodels}
  નિદર્શ~$\mModel M$માં \emph{!!a{formula}~$!A$નું~$w$માં સત્ય હોવું},
  સંજ્ઞામાં $\mSat{M}{!A}[w]$, નીચે મુજબ આગમનાત્મક રીતે
  વ્યાખ્યાયિત થાય છે:
  \begin{enumerate}
  \tagitem{prvFalse}{\indcase{!A}{\lfalse}{$\mSat{M}{\lfalse}[w]$ ક્યારેય નહીં}.}{}
  \tagitem{prvTrue}{\indcase{!A}{\ltrue}{$\mSat{M}{\ltrue}[w]$ હંમેશા}.}{}
  \item $\mSat{M}{p}[w]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે $w \in V(p)$
  \tagitem{prvNot}{\indcase{!A}{\lnot !B}{$\mSat{M}{\indfrm}[w]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે
    $\mSat/{M}{!B}[w]$}.}{}
  \tagitem{prvAnd}{\indcase{!A}{(!B \land !C)}{$\mSat{M}{\indfrm}[w]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે
    $\mSat{M}{!B}[w]$ અને $\mSat{M}{!C}[w]$}.}{}
  \tagitem{prvOr}{\indcase{!A}{(!B \lor !C)}{$\mSat{M}{\indfrm}[w]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે
    $\mSat{M}{!B}[w]$ અથવા $\mSat{M}{!C}[w]$} (અથવા બંને).}{}
  \tagitem{prvIf}{\indcase{!A}{(!B \lif !C)}{$\mSat{M}{\indfrm}[w]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે
    $\mSat/{M}{!B}[w]$ અથવા $\mSat{M}{!C}[w]$}.}{}
  \tagitem{prvIff}{\indcase{!A}{(!B \liff !C)}{$\mSat{M}{\indfrm}[w]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે
    $\mSat{M}{!B}[w]$ અને $\mSat{M}{!C}[w]$ બંને હોય, અથવા
    $\mSat{M}{!B}[w]$ તથા $\mSat{M}{!C}[w]$ બેમાંથી એકેય ન હોય}.}{}
  \item\ollabel{defn:sub:mmodels-box}
    \indcase{!A}{\Knows_a !B}{$\mSat{M}{\indfrm}[w]$ ત્યારે અને માત્ર ત્યારે જ જ્યારે
    $R_a ww'$ ધરાવતા દરેક $w' \in W$ માટે $\mSat{M}{!B}[w']$}
  \end{enumerate} 
\end{defn}

