\begin{defn}[!!^{derivability}]
જો $\Gamma$માંથી અંતે $!A$ આવતું !!a{derivation} હોય, તો
!!^a{formula}~$!A$ એ $\Gamma$માંથી \emph{!!{derivable}}
છે; તેને $\Gamma \Proves !A$ લખીએ છીએ.
\end{defn}

source_text:
\begin{defn}[Theorems]
!!^a{formula}~$!A$ is a \emph{theorem} if there is !!a{derivation}
of~$!A$ from the empty set.  We write $\Proves !A$ if $!A$ is a
theorem and $\Proves/ !A$ if it is not.
\end{defn}

\begin{prop}
  If $\Gamma \Proves !A$ in the axiomatic !!{derivation} system for
  intuitionistic logic, $\Gamma \Proves !A$ also in
  classical logic. In particular, if $!A$ is an intuitionistic
  theorem, it is also a classical theorem.
\end{prop}

