\begin{prop}\ollabel{prop:sat-entails}
  \begin{enumerate}
  \item\ollabel{prop:sat-entails1} If $\mSat{M}{\Gamma}[w]$ and
    $\Gamma \Entails !A$, then $\mSat{M}{!A}[w]$.
  \item\ollabel{prop:sat-entails2} If $\mSat{M}{\Gamma}$ and $\Gamma
    \Entails !A$, then $\mSat{M}{!A}$.
  \end{enumerate}
\end{prop}

