\begin{prop}\ollabel{prop:sat-entails}
  \begin{enumerate}
  \item\ollabel{prop:sat-entails1} જો $\mSat{M}{\Gamma}[w]$ અને
    $\Gamma \Entails !A$ હોય, તો $\mSat{M}{!A}[w]$.
  \item\ollabel{prop:sat-entails2} જો $\mSat{M}{\Gamma}$ અને $\Gamma
    \Entails !A$ હોય, તો $\mSat{M}{!A}$.
  \end{enumerate}
\end{prop}

source_text:
\begin{proof}
  \begin{enumerate}
  \item Suppose $\mSat{M}{\Gamma}$. Since $\Gamma \Entails !A$, we
    know that if $\mSat{M}{\Gamma}[w]$, then $\mSat{M}{!A}[w]$. Since
    $\mSat{M}{\Gamma}[u]$ for all every $u \in W$,
    $\mSat{M}{\Gamma}[w]$. Hence $\mSat{M}{!A}[w]$.
  \item Follows immediately from \olref{prop:sat-entails1}.
  \end{enumerate}
\end{proof}

