\begin{defn}\ollabel{defn:restrict}
  Suppose $\mModel{M}$ is a relational model and $w \in W$. The
  \emph{restriction} $\mModel{M}_w=\tuple{W_w, R_w, V_w}$
  of~$\mModel{M}$ to~$w$ is given by:
  \begin{align*}
    W_w & = \Setabs{u \in W}{Rwu},\\
    R_w  & = R \cap (W_w)^2, \text{ and}\\
    V_w(p) & = V(p) \cap W_w.
  \end{align*}
\end{defn}

target_text:
\begin{defn}\ollabel{defn:restrict}
  ધારો કે $\mModel{M}$ એ સંબંધાત્મક નિદર્શ છે અને $w \in W$.
  $\mModel{M}$નું~$w$ સુધીનું \emph{મર્યાદન}
  $\mModel{M}_w=\tuple{W_w, R_w, V_w}$ આ પ્રમાણે છે:
  \begin{align*}
    W_w & = \Setabs{u \in W}{Rwu},\\
    R_w  & = R \cap (W_w)^2, \text{ અને}\\
    V_w(p) & = V(p) \cap W_w.
  \end{align*}
\end{defn}

