\begin{defn}\ollabel{defn:prime}
  A set of !!{formula}s~$\Gamma$ is \emph{prime} iff 
  \begin{enumerate}
  \item\ollabel{defn:prime1} $\Gamma$ is consistent, i.e., $\Gamma \Proves/ \lfalse$;
  \item\ollabel{defn:prime2} if $\Gamma \Proves !A$ then $!A \in \Gamma$; and
  \item\ollabel{defn:prime3} if $!A \lor !B \in \Gamma$ then $!A \in
    \Gamma$ or $!B \in \Gamma$.
  \end{enumerate}
\end{defn}

target_text:
\begin{defn}\ollabel{defn:prime}
  !!{formula}sનો ગણ~$\Gamma$ ત્યારે અને માત્ર ત્યારે જ
  \emph{અભાજ્ય} કહેવાય જ્યારે
  \begin{enumerate}
  \item\ollabel{defn:prime1} $\Gamma$ સુસંગત હોય, એટલે
    $\Gamma \Proves/ \lfalse$;
  \item\ollabel{defn:prime2} જો $\Gamma \Proves !A$ હોય,
    તો $!A \in \Gamma$; અને
  \item\ollabel{defn:prime3} જો $!A \lor !B \in \Gamma$
    હોય, તો $!A \in \Gamma$ અથવા $!B \in \Gamma$.
  \end{enumerate}
\end{defn}

