\begin{prob}
  Show that if $!A$ only contains !!{propositional variable}s, $\lor$,
  and~$\land$, then $\Entails/ !A$. Use this to conclude that $\lif$ is
  not definable in intuitionistic logic from $\lor$ and~$\land$. 
\end{prob}

target_text:
\begin{prob}
  જો $!A$માં ફક્ત !!{propositional variable}s, $\lor$
  અને~$\land$ હોય, તો $\Entails/ !A$ છે તે બતાવો.
  આ પરથી સ્ફુરણાવાદી તર્કમાં $\lor$ અને~$\land$
  વડે $\lif$ વ્યાખ્યાયિત થઈ શકતું નથી તે તારવો.
\end{prob}

