\begin{prob}
  By using the completeness theorem prove that if $\Proves !A \lor !B$ then
  $\Proves !A$ or $\Proves !B$. (Hint: Assume $\mSat/{M_1}{!A}$ and
  $\mSat/{M_2}{!B}$ and construct a new model $\mModel{M}$ such that
  $\mSat/{M}{!A \lor !B}$.)
\end{prob}

\begin{prob} 
