source_text:
\begin{defn}
  $\mSat{M}{!B \cif !C}[w]$ iff either
  \begin{enumerate}
  \item\ollabel{sphere-vac} For all $u \in \bigcup O_w$, $\mSat/{M}{!B}[u]$, or
  \item\ollabel{sphere-nonvac} For some $S \in O_w$,
    \begin{enumerate}
      \item $\mSat{M}{!B}[u]$ for some $u \in
        S$, and
      \item for all $v \in S$, either
        $\mSat/{M}{!B}[v]$ or $\mSat{M}{!C}[v]$.
    \end{enumerate}
  \end{enumerate}
\end{defn}

target_text:
\begin{defn}
  $\mSat{M}{!B \cif !C}[w]$ ત્યારે અને માત્ર ત્યારે જ્યારે નીચેની
  બેમાંથી કોઈ એક શરત સંતોષાય:
  \begin{enumerate}
  \item\ollabel{sphere-vac} દરેક $u \in \bigcup O_w$ માટે $\mSat/{M}{!B}[u]$, અથવા
  \item\ollabel{sphere-nonvac} કોઈ $S \in O_w$ માટે,
    \begin{enumerate}
      \item કોઈ $u \in
        S$ માટે $\mSat{M}{!B}[u]$, અને
      \item દરેક $v \in S$ માટે કાં તો
        $\mSat/{M}{!B}[v]$ અથવા $\mSat{M}{!C}[v]$.
    \end{enumerate}
  \end{enumerate}
\end{defn}

source_text:
A counterfactual $!A \cif !B$ is (non-vacuously) true if the closest
$!A$-worlds are all $!B$-worlds, as depicted in \olref{fig:true}.
\begin{figure}
\begin{center}
\begin{tikzpicture}[scale=.7]\small
  \spheresystem{5}
  \draw (0,0) node {$w$};
  \propositionintersect{0}{4}{40}{3.5}
  {\tikzset{proposition/.append={smooth,tension=1.4}}
  \proposition[shift={(1.6,-1)}]{90}{1}{30}{4}}
  \path (1.5,3) node[below] {$\formula{B}$};
  \path (3,0) node {$\formula{A}$};
\end{tikzpicture}
\caption{Non-vacuously true counterfactual}
\ollabel{fig:true}
\end{center}
\end{figure}
A counterfactual is also true at $w$ if the system of spheres
around~$w$ has no $!A$-admitting spheres at all. In that case it is
\emph{vacuously} true (see  \olref{fig:vacuous}).
\begin{figure}
\begin{center}
\begin{tikzpicture}[scale=.7]\small
  \spheresystem{5}
