  \path (1.5,3) node[below] {$\formula{B}$};
  \spherepos{0}{7}{node {$\formula{A}$}}
\end{tikzpicture}
\caption{Vacuously true counterfactual}
\ollabel{fig:vacuous}
\end{center}
\end{figure}

