\begin{defish}
  \emph{Na\"{i}ve Comprehension.} $\Setabs{x}{\phi(x)}$ exists for any formula $\phi$.
\end{defish}

target_text:
\begin{defish}
  \emph{સહજ ગણરચના.} કોઈ પણ સૂત્ર $\phi$ માટે $\Setabs{x}{\phi(x)}$ અસ્તિત્વ ધરાવે છે.
\end{defish}

source_text:
\begin{thm}[Russell's Paradox]
There is no set $R = \Setabs{x}{x \notin x}$
\end{thm}

target_text:
\begin{thm}[રસેલનો વિરોધાભાસ]
$R = \Setabs{x}{x \notin x}$ એવો કોઈ ગણ નથી.
\end{thm}

source_text:
\begin{proof}
If $R = \Setabs{x}{x \notin x}$ exists, then
$R \in R$ iff $R \notin R$, which is a contradiction.
\end{proof}

target_text:
\begin{proof}
જો $R = \Setabs{x}{x \notin x}$ અસ્તિત્વ ધરાવતો હોય, તો
$R \in R$ ત્યારે અને માત્ર ત્યારે જ્યારે $R \notin R$, જે પરસ્પરવિરોધ છે.
\end{proof}

source_text:
\begin{defish}
\emph{Predicative Comprehension.} For every formula $\phi$ quantifying only over sets: the set$^\prime$ $\Setabs{x}{\phi(x)}$ exists.
\end{defish}

target_text:
