\begin{thm}[in $\Z$ + Weak-Reflection]\label{thm:replacement} 
For any formula $\phi(v,w)$, and any $A$, if $(\forall x \in A)\lexists![y][\phi(x,y)]$, then
$\Setabs{y}{(\exists x \in A)\phi(x,y}$ exists.
\end{thm}

