\begin{thm}
The set of all cardinals does not exist.
\end{thm}

target_text:
\begin{thm}
બધા ગણાંકોનો ગણ અસ્તિત્વમાં નથી.
\end{thm}

source_text:
\begin{proof}
For reductio, suppose $C = \Setabs{\cardfont{a}}{\cardfont{a} \text{
is a cardinal}}$. Now $\bigcup C$ is a cardinal by
\olref{unioncardinalscardinal}, so by \olref{lem:NoLargestCardinal}
there is a cardinal $\cardfont{b} > \bigcup C$. By definition
$\cardfont{b} \in C$, so $\cardfont{b} \subseteq \bigcup{C}$, so that
$\cardfont{b} \leq \bigcup C$, a contradiction.
\end{proof}

target_text:
\begin{proof}
વિરોધાભાસ માટે ધારો કે $C = \Setabs{\cardfont{a}}{\cardfont{a} \text{
ગણાંક છે}}$. હવે \olref{unioncardinalscardinal}
મુજબ $\bigcup C$ ગણાંક છે; તેથી
\olref{lem:NoLargestCardinal} મુજબ કોઈ ગણાંક
$\cardfont{b} > \bigcup C$ છે. વ્યાખ્યાથી
$\cardfont{b} \in C$, એટલે
$\cardfont{b} \subseteq \bigcup{C}$, તેથી
$\cardfont{b} \leq \bigcup C$; આ વિરોધાભાસ છે.
\end{proof}

source_text:
\begin{defn}
When $\cardfont{a}$ and $\cardfont{b}$ are cardinals:
\begin{align*}
	\cardfont{a} \cardplus \cardfont{b} &\defis 
	\card{\cardfont{a} \disjointsum \cardfont{b}}\\
	\cardfont{a} \cardtimes \cardfont{b} &\defis 
	\card{\cardfont{a} \times \cardfont{b}}\\
	\cardexpo{\cardfont{a}}{\cardfont{b}} &\defis 
	\card{\funfromto{\cardfont{b}}{\cardfont{a}}}
\end{align*}
where $\funfromto{X}{Y} = \Setabs{f}{f \text{ is a function } X \to Y}$.
(It is easy to show that $\funfromto{X}{Y}$ exists for any sets $X$
and $Y$; we leave this as an exercise.) 
\end{defn}

target_text:
\begin{defn}
$\cardfont{a}$ અને $\cardfont{b}$ ગણાંકો હોય ત્યારે:
\begin{align*}
	\cardfont{a} \cardplus \cardfont{b} &\defis 
	\card{\cardfont{a} \disjointsum \cardfont{b}}\\
	\cardfont{a} \cardtimes \cardfont{b} &\defis 
	\card{\cardfont{a} \times \cardfont{b}}\\
	\cardexpo{\cardfont{a}}{\cardfont{b}} &\defis 
	\card{\funfromto{\cardfont{b}}{\cardfont{a}}}
\end{align*}
અહીં $\funfromto{X}{Y} = \Setabs{f}{f \text{ એ વિધેય છે } X \to Y}$.
(કોઈ પણ ગણો $X$ અને $Y$ માટે
$\funfromto{X}{Y}$ અસ્તિત્વમાં છે તે બતાવવું સહેલું
છે; તેને સ્વાધ્યાય તરીકે છોડીએ છીએ.)
\end{defn}

