source_text:
\begin{lem}\ollabel{lem:SizePowerset2Exp}
$\card{\Pow{A}} = \cardexpo{2}{\card{A}}$, for any $A$.
\end{lem}

target_text:
\begin{lem}\ollabel{lem:SizePowerset2Exp}
કોઈ પણ $A$ માટે $\card{\Pow{A}} =
\cardexpo{2}{\card{A}}$.
\end{lem}

source_text:
\begin{proof}
For each subset $B \subseteq A$, let $\chi_B \in \funfromto{A}{2}$ be given by:
\begin{align*}
	\chi_{B}(x) &\defis
	\begin{cases}
		1 & \text{if }x\in B\\
		0 & \text{otherwise.}
	\end{cases}
\end{align*}
Now let $f(B) = \chi_B$; this defines !!a{bijection} $f \colon \Pow{A}
\to \funfromto{A}{2}$. So $\cardeq{\Pow{A}}{\funfromto{A}{2}}$. Hence
$\cardeq{\Pow{A}}{\funfromto{\card{A}}{2}}$, so that
$\card{\Pow{A}} = \card{\funfromto{\card{A}}{2}} =
2^{\card{A}}$.
\end{proof}

target_text:
\begin{proof}
દરેક ઉપગણ $B \subseteq A$ માટે
$\chi_B \in \funfromto{A}{2}$ આ રીતે લો:
\begin{align*}
	\chi_{B}(x) &\defis
	\begin{cases}
		1 & \text{જો }x\in B\\
		0 & \text{અન્યથા.}
	\end{cases}
\end{align*}
હવે $f(B) = \chi_B$ લો; આથી
!!a{bijection} $f \colon \Pow{A} \to
\funfromto{A}{2}$ વ્યાખ્યાયિત થાય છે.
તેથી $\cardeq{\Pow{A}}{\funfromto{A}{2}}$.
આથી $\cardeq{\Pow{A}}{\funfromto{\card{A}}{2}}$,
અને તેથી $\card{\Pow{A}} =
\card{\funfromto{\card{A}}{2}} = 2^{\card{A}}$.
\end{proof}

source_text:
\begin{cor}\ollabel{cantorcor}
$\cardfont{a} < \cardexpo{2}{\cardfont{a}}$ for any cardinal~$\cardfont{a}$.
\end{cor}

target_text:
\begin{cor}\ollabel{cantorcor}
કોઈ પણ ગણાંક~$\cardfont{a}$ માટે
$\cardfont{a} < \cardexpo{2}{\cardfont{a}}$.
\end{cor}

\begin{proof}
