\begin{align*}
	B &= \ran{f}\\
	R &= \Setabs{\tuple{f(\gamma), f(\delta)} \in A \times A}{\gamma,\delta\in\alpha \land \gamma \in \delta}.
\end{align*}
સ્પષ્ટપણે $\alpha = \ordtype{B, R}$ અને
$\tuple{B, R} \in C$. તેથી $\alpha
\in \alpha$, જે વિરોધાભાસ છે.
\sourcecorrection{OLMD-145}{મૂળ સંબંધ-સૂત્રમાં
$f(\alpha)$ છે, પરંતુ $f$નું ક્ષેત્ર $\alpha$
હોવાથી $f(\alpha)$ વ્યાખ્યાયિત નથી.
સંબંધની જોડી માટે $\gamma,\delta\in\alpha$
એવા નવા સૂચકો લીધા છે અને
$\gamma\in\delta$ શરત સ્પષ્ટ કરી છે.}
\end{proof}

source_text:
\begin{thm}[\emph{in $\ZF$}]
The following claims are equivalent:
\begin{enumerate}
	\item\ollabel{equivwo} The Axiom of Well-Ordering
	\item\ollabel{equivcompare} Either $\cardle{A}{B}$ or
	$\cardle{B}{A}$, for any sets $A$ and $B$
\end{enumerate}
\end{thm}

target_text:
\begin{thm}[\emph{$\ZF$માં}]
નીચેના દાવા સમકક્ષ છે:
\begin{enumerate}
	\item\ollabel{equivwo} સુક્રમિતતાની સ્વયંસિદ્ધિ
	\item\ollabel{equivcompare} કોઈ પણ ગણો $A$ અને $B$ માટે
	$\cardle{A}{B}$ અથવા $\cardle{B}{A}$
\end{enumerate}
\end{thm}

source_text:
\begin{defn}
A function $f$ is a \emph{choice function} iff $f(x) \in x$ for all $x \in \dom{f}$. We say that $f$ is a \emph{choice function for $A$} iff $f$ is a choice function with $\dom{f} = A \setminus \{\emptyset\}$.
\end{defn}

\begin{axiom}[Choice]
	Every set has a choice function.
\end{axiom}

target_text:
\begin{axiom}[પસંદગી]
	દરેક ગણ માટે પસંદગી વિધેય છે.
\end{axiom}

source_text:
\begin{thm}[in $\ZF$]\ollabel{thmwochoice}
Well-Ordering and Choice are equivalent.
\end{thm}

target_text:
\begin{thm}[$\ZF$માં]\ollabel{thmwochoice}
સુક્રમિતતા અને પસંદગી સમકક્ષ છે.
\end{thm}

source_text:
\begin{lem}[in $\Zminus$]
Every finite set has a choice function. 
\end{lem}

target_text:
\begin{lem}[$\Zminus$માં]
દરેક સાન્ત ગણ માટે પસંદગી વિધેય છે.
\end{lem}

\begin{proof}
$a = \{b_1, \ldots, b_n\}$ લો. સરળતા માટે
દરેક $b_i \neq \emptyset$ ધારો. તેથી
$c_1 \in b_1, \ldots, c_n \in b_n$
એવી વસ્તુઓ $c_1, \ldots, c_n$ છે.
હવે \olref[z][pairs]{prop:pairsconsequences}
મુજબ $\{\langle b_1,
c_1\rangle , \ldots, \langle b_n, c_n\rangle\}$
ગણ છે; અને એ $a$ માટેનું પસંદગી વિધેય છે.
\end{proof}

source_text:
\begin{defish}
\emph{Countable Choice.} Every \emph{countable} set has a choice function. 
\end{defish}

target_text:
\begin{defish}
\emph{ગણનીય પસંદગી.} દરેક \emph{ગણનીય}
ગણ માટે પસંદગી વિધેય છે.
\end{defish}

આ પસંદગીનો ખાસ કિસ્સો છે. જાણવા મળે છે
કે આ સિદ્ધાંતનો ઉપયોગ તેની સ્પષ્ટ જાણ
વિના ઘણી વાર થયો હતો. બે સરસ ઉદાહરણો
આ છે.\footnote{\citet[\S9.4]{Potter2004}
અને લૂકા ઇન્કુર્વાતી પાસેથી.}

source_text:
\begin{thm}[in $\ZF$]\ollabel{choiceset}
Choice is equivalent to the following principle. If the !!{element}s
of $A$ are disjoint and non-empty, then there is some $C$ such that $C
\cap x$ is a singleton for every $x \in A$. (We call such a $C$ a
{choice set} for $A$.)
\end{thm}

\begin{prob}
Prove \olref[sth][choice][justifications]{choiceset}. If you struggle,
you can find a proof in \cite[pp.~242--3]{Potter2004}.
\end{prob}

target_text:
\begin{prob}
\olref[sth][choice][justifications]{choiceset}
સાબિત કરો. મુશ્કેલી પડે તો
\cite[pp.~242--3]{Potter2004}માં
પુરાવો મળશે.
\end{prob}

source_text:
Sometimes, however, it is claimed that Choice has \emph{undesirable}
consequences. Mostly, this is due to a result by
\cite{BanachTarski1924}.

\begin{thm}[Vitali's Paradox (in $\ZFC$)]\ollabel{vitaliparadox}
Any circle can be decomposed into countably many pieces, which can be
reassembled (by rotation and transportation) to form two copies of
that circle.
\end{thm}

target_text:
\begin{thm}[વિટાલીનો વિરોધાભાસ ($\ZFC$માં)]\ollabel{vitaliparadox}
કોઈ પણ વર્તુળને ગણનીય સંખ્યામાં ટુકડાઓમાં
વિભાજિત કરી શકાય છે; એ ટુકડાઓને
(પરિભ્રમણ અને સ્થાનાંતરણથી) ફરી ગોઠવી
તે વર્તુળની બે નકલો બનાવી શકાય છે.
\end{thm}

