$s_{k+1}$ શું છે? વ્યાખ્યા મુજબ $s_{k+1} = s_k + (k+1)$.
  આગમન-પરિકલ્પના મુજબ $s_k = k(k+1)/2$. તેને અગાઉના
  સમીકરણમાં મૂકીએ તો માત્ર થોડું અપૂર્ણાંકોનું ગણિત બાકી રહે છે:
  \begin{align*}
    s_{k+1} & = \frac{k(k+1)}{2} + (k+1) = {}\\
    & = \frac{k(k+1)}{2} + \frac{2(k+1)}{2} = {}\\
    & = \frac{k(k+1) + 2(k+1)}{2} = {}\\
    & = \frac{(k+2)(k+1)}{2}.
  \end{align*}
\end{proof}

source_text:
\begin{defn}[Nice terms]
  The set of \emph{nice terms} is inductively defined as follows:
  \begin{enumerate}
  \item Any letter $\mathrm{a}$, $\mathrm{b}$, $\mathrm{c}$,
    $\mathrm{d}$ is a nice term.
  \item If $s_1$ and $s_2$ are nice terms, then so
    is $[s_1 \circ s_2]$.
  \item Nothing else is a nice term.
  \end{enumerate}
\end{defn}

\begin{prop}
  For any $n$, the number of $[$ in a nice term of length~$n$ is
  $< n/2$.
\end{prop}

target_text:
\begin{prop}
  કોઈ પણ $n$ માટે લંબાઈ~$n$ના સુઘડ પદમાં
  $[$ની સંખ્યા $< n/2$ છે.
\end{prop}

source_text:
\begin{prob}
  Define the set of supernice terms by
  \begin{enumerate}
  \item Any letter $\mathrm{a}$, $\mathrm{b}$, $\mathrm{c}$,
    $\mathrm{d}$ is a supernice term.
  \item If $s$ is a supernice term, then so is $[s]$.
  \item If $s_1$ and $s_2$ are supernice terms, then so
    is $[s_1 \circ s_2]$.
  \item Nothing else is a supernice term.
  \end{enumerate}
  Show that the number of $[$ in a supernice term~$t$ of length~$n$ is
    $\le n/2 +1$.
\end{prob}

target_text:
\begin{prob}
  અતિસુઘડ પદોનો ગણ આ રીતે વ્યાખ્યાયિત કરો:
  \begin{enumerate}
  \item કોઈ પણ અક્ષર $\mathrm{a}$, $\mathrm{b}$, $\mathrm{c}$,
    $\mathrm{d}$ અતિસુઘડ પદ છે.
  \item $s$ અતિસુઘડ પદ હોય તો $[s]$ પણ છે.
  \item $s_1$ અને $s_2$ અતિસુઘડ પદો હોય, તો
    $[s_1 \circ s_2]$ પણ છે.
  \item આ સિવાય બીજું કંઈ અતિસુઘડ પદ નથી.
  \end{enumerate}
  લંબાઈ~$n$ના અતિસુઘડ પદ~$t$માં $[$ની
  સંખ્યા $\le n/2 +1$ છે એમ બતાવો.
\end{prob}

