source_text:
\begin{defn}
  The relation of a nice term~$t_1$ being a subterm of~$t_2$, $t_1
  \sqsubseteq t_2$, is defined by induction on~$t_2$ as follows:
  \begin{enumerate}
  \item If $t_2$ is a letter, then $t_1 \sqsubseteq t_2$ iff $t_1 = t_2$.
  \item If $t_2$ is $[s_1 \circ s_2]$, then $t_1 \sqsubseteq t_2$ iff $t_1 =
    t_2$, $t_1 \sqsubseteq s_1$, or $t_1 \sqsubseteq s_2$.
  \end{enumerate}
\end{defn}

target_text:
\begin{defn}
  સુઘડ પદ~$t_1$ એ~$t_2$નું ઉપપદ છે એવો સંબંધ,
  $t_1 \sqsubseteq t_2$,~$t_2$ પરના આગમનથી
  નીચે મુજબ વ્યાખ્યાયિત થાય છે:
  \begin{enumerate}
  \item $t_2$ અક્ષર હોય તો $t_1 \sqsubseteq t_2$
    ત્યારે અને ત્યારે જ જ્યારે $t_1 = t_2$.
  \item $t_2$ એ $[s_1 \circ s_2]$ હોય તો
    $t_1 \sqsubseteq t_2$ ત્યારે અને ત્યારે જ જ્યારે
    $t_1 = t_2$, $t_1 \sqsubseteq s_1$ અથવા
    $t_1 \sqsubseteq s_2$.
  \end{enumerate}
\end{defn}

source_text:
\begin{defn}
  Define \emph{bracketless terms} inductively by
  \begin{enumerate}
  \item Every letter is a bracketless term.
    \item If $s_1$ and $s_2$ are bracketless terms, then $s_1 \circ s_2$ is
      a bracketless term.
    \item Nothing else is a bracketless term.
  \end{enumerate}
\end{defn}

target_text:
\begin{defn}
  \emph{કૌંસવિહોણાં પદો} આગમનાત્મક રીતે
  આ પ્રમાણે વ્યાખ્યાયિત કરો:
  \begin{enumerate}
  \item દરેક અક્ષર કૌંસવિહોણું પદ છે.
    \item $s_1$ અને $s_2$ કૌંસવિહોણાં પદો
      હોય તો $s_1 \circ s_2$ પણ કૌંસવિહોણું
      પદ છે.
    \item આ સિવાય બીજું કંઈ કૌંસવિહોણું પદ નથી.
  \end{enumerate}
\end{defn}

