\begin{defn}[Maximally consistent set]
\ollabel{mcs}
A set~$\Gamma$ of !!{sentence}s is \emph{maximally consistent} iff
\begin{enumerate}
\item $\Gamma$ is consistent, and
\item if $\Gamma \subsetneq \Gamma'$, then $\Gamma'$ is inconsistent.
\end{enumerate}
\end{defn}

