\begin{prop}[Compactness]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item If $\Gamma \Proves !A$ then there is a finite subset $\Gamma_0
    \subseteq \Gamma$ such that $\Gamma_0 \Proves !A$.
  \item If every finite subset of~$\Gamma$ is
    consistent, then $\Gamma$ is consistent.
  \end{enumerate}
\end{prop}

target_text:
\begin{prop}[સઘનતા]
  \ollabel{prop:proves-compact}
  \begin{enumerate}
  \item જો $\Gamma \Proves !A$ હોય, તો
    એવો સાન્ત ઉપગણ $\Gamma_0
    \subseteq \Gamma$ છે કે
    $\Gamma_0 \Proves !A$.
  \item જો $\Gamma$નો દરેક
    સાન્ત ઉપગણ સુસંગત હોય,
    તો $\Gamma$ સુસંગત છે.
  \end{enumerate}
\end{prop}

source_text:
\begin{proof}
  \begin{enumerate}
    \item If $\Gamma \Proves !A$, then there is a finite subset
      $\Gamma_0 \subseteq \Gamma$ such that the sequent $\Gamma_0
      \Sequent !A$ has !!a{derivation}. Consequently, $\Gamma_0
      \Proves !A$.
    \item If $\Gamma$ is inconsistent, there is a finite
      subset~$\Gamma_0 \subseteq \Gamma$ such that $\Log{LK}$
      !!{derive}s $\Gamma_0 \Sequent \quad$. But then $\Gamma_0$ is a
      finite subset of~$\Gamma$ that is inconsistent.
  \end{enumerate}
\end{proof}

\begin{defn}
Let $\Lang{L_N}$ be the !!{language} of arithmetic, comprising a
!!{constant} $\Obj{0}$, a 2-place !!{predicate} $<$, a 1-place
!!{function} $\prime$, and 2-place !!{function}s $+$ and $\times$.
\begin{enumerate}
\item The \emph{standard model} of arithmetic is the !!{structure}
  $\Struct{N}$ for $\Lang{L_N}$ having $\Nat = \{ 0, 1, 2, \dots\}$
  and interpreting $\Obj{0}$ as $0$, $<$ as the less-than relation
  over~$\Nat$, and $\prime$, $+$ and $\times$ as successor, addition,
  and multiplication over $\Nat$, respectively.
\item \emph{True arithmetic} is the theory $\Theory{N}$.
\end{enumerate}
\end{defn}

\begin{defn}
A !!{structure}~$\Struct{M}$ for $\Lang{L_N}$ is \emph{standard} if
