\begin{defn}
Consider !!a{proof}~$\pi$ ending in a \CutCS{} rule,
\[
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$\Gamma \fCenter \Delta, !A$
\AxiomC{}
\RightLabel{$\pi_2$}
\Deduce$!A, \Gamma \fCenter \Delta$
\RightLabel{\CutCS}
\BinaryInf$\Gamma \fCenter \Delta$
\DisplayProof
\]
and containing no other \CutCS{} inferences. The \emph{cut height}
of~$\pi$ is $\cheight{\pi} = \pheight{\pi_1} + \pheight{\pi_2}$. The
\emph{cut rank} of~$\pi$ is $\cutrank{\pi} = \depth{!A}$.
\end{defn}

target_text:
\begin{defn}
\CutCS{} નિયમથી પૂરી થતી !!a{proof}~$\pi$ લો,
\[
\AxiomC{}
\RightLabel{$\pi_1$}
\Deduce$\Gamma \fCenter \Delta, !A$
\AxiomC{}
\RightLabel{$\pi_2$}
\Deduce$!A, \Gamma \fCenter \Delta$
\RightLabel{\CutCS}
\BinaryInf$\Gamma \fCenter \Delta$
\DisplayProof
\]
અને તેમાં બીજું કોઈ \CutCS{} અનુમાન ન હોય.
~$\pi$ની \emph{કટ-ઊંચાઈ}
$\cheight{\pi} = \pheight{\pi_1} + \pheight{\pi_2}$ છે.
~$\pi$નો \emph{કટ-ક્રમ}
$\cutrank{\pi} = \depth{!A}$ છે.
\end{defn}

