\begin{thm}\ollabel{thm:cut-elim-G3c-topmost} Any !!{proof} $\pi$ in
$\Log{G3c} + \CutCS$ can be transformed into !!a{proof} in~\Log{G3c}.
\end{thm}

target_text:
\begin{thm}\ollabel{thm:cut-elim-G3c-topmost}
$\Log{G3c} + \CutCS$ની કોઈ પણ
!!{proof}~$\pi$ને~\Log{G3c}ની
!!a{proof}માં ફેરવી શકાય છે.
\end{thm}

source_text:
\begin{proof}
  By induction on the number~$n$ of \CutCS{} inferences in~$\pi$. If
  $n=0$, there is nothing to do: $\pi$ is already !!a{proof}
  in~\Log{G3c}. Otherwise, consider the sub-!!{proof}~$\pi'$ ending in
  a top-most \CutCS{} inference. It contains a single \CutCS{} rule as the
  last inference. Apply \olref{lem:cut-adm-G3c} to transform it into a
  \CutCS{}-free proof~$\pi''$, and replace the sub-!!{proof}~$\pi'$
  by~$\pi''$. The result is !!a{proof} containing $n-1$ \CutCS{}
  inferences, and the induction hypothesis applies.
\end{proof}

\begin{lem}[Maehara's Lemma]\ollabel{lem:maehara} If $\Log{G3c}
\Proves \maeh{\Gamma_1}{\Gamma_2} \Sequent \maeh{\Delta_1}{\Delta_2}$
then there is !!a{formula}~$!C$ in the !!{language}~$\Lang L(!C)
\subseteq \Lang L(\Gamma_1,
\Delta_1) \cap \Lang L(\Gamma_2, \Delta_2)$ such that $\Log{G3c}
\Proves \Gamma_1 \Sequent \Delta_1, !C$ and $\Log{G3c} \Proves !C,
\Gamma_2 \Sequent \Delta_2$.
\end{lem}

target_text:
માએહારાનું ઉપપ્રમેય મળ્યું છે;
હવે તે વડે ક્રેગનું અંતર્વેશન
પ્રમેય સાબિત કરીએ.

source_text:
\begin{proof}[Proof of \olref{thm:interpolation}]
  Suppose $!A \Sequent !B$ is !!{provable}. Apply \olref{lem:maehara}
  to $\maeh{!A}{\ } \Sequent \maeh{\ }{!B}$ to obtain the
  interpolant~$!C$. We have $\Proves !A \Sequent !C$ and $\Proves !C
  \Sequent !B$.
\end{proof}

\begin{lem}[Beth Definability Theorem]
  If $\Gamma$ implicitly defines~$R$ then it also explicitly defines it.
\end{lem}

\begin{proof}
  Suppose $\Gamma$ implicitly defines~$R$. Let $R'$, $\Gamma'$ be as
  above and $\Lang L' = \Lang L(\Gamma') = \Lang L \setminus \{R\}
  \cup \{R'\}$. By hypothesis, we have
  \begin{align*}
    \Gamma, \Gamma' & 
    \Sequent \lforall[x_1][\dots\lforall[x_n][(R(x_1,\dots,x_n) 
    \liff R'(x_1, \dots, x_n))]]
  \intertext{Let $c_1$, \dots,~$c_n$ be !!{constant}s not occurring in~$\Gamma$. By the invertibility lemma we have}
    \Gamma, \Gamma', R(c_1,\dots,c_n) & \Sequent  R'(c_1, \dots, c_n)
  \intertext{Apply Maehara's Lemma to}
    \maeh{\Gamma, R(c_1,\dots,c_n)}{\Gamma'} & \Sequent
      \maeh{\ }{R'(c_1, \dots, c_n)}
  \intertext{to find an~$!A \ident !A(x_1, \dots, x_n)$ such that}
    \Gamma, R(c_1,\dots,c_n) & \Sequent !A(c_1, \dots, c_n) \\
    !A(c_1, \dots, c_n), \Gamma' & \Sequent R'(c_1, \dots, c_n)
  \intertext{have !!{proof}s. Since $\Lang L(!A) = \Lang L_1 \cap
  \Lang L_2 = \Lang L(\Gamma) \setminus \{R\}$, $!A$~does not contain~$R$.
  Replace $R'$ everywhere by~$R$ in the !!{proof} of the second sequent
  to get !!a{proof} of}
    !A(c_1, \dots, c_n), \Gamma & \Sequent R(c_1, \dots, c_n)
  \end{align*}
  Apply \RightR{\lif} and \RightR{\lforall} to get !!a{proof} of
  \[
    \Gamma \Sequent \lforall[x_1][\dots\lforall[x_n][(R(x_1,\dots,x_n) \liff !A(x_1, \dots, x_n))]].
  \]
  This shows that $!A(x_1, \dots, x_n)$ explicitly defines $!R$
  in~$\Gamma$.
\end{proof}

target_text:
\begin{proof}
  માનો કે~$\Gamma$ એ~$R$ને ગૂઢ રીતે
  વ્યાખ્યાયિત કરે છે.
  ઉપર મુજબ~$R'$ અને~$\Gamma'$
  લો તથા
  $\Lang L' = \Lang L(\Gamma') =
  \Lang L \setminus \{R\}
  \cup \{R'\}$.
  પૂર્વધારણાથી મળે છે:
  \begin{align*}
    \Gamma, \Gamma' & 
    \Sequent \lforall[x_1][\dots\lforall[x_n][(R(x_1,\dots,x_n) 
    \liff R'(x_1, \dots, x_n))]]
  \intertext{$c_1$, \dots,~$c_n$ એ $\Gamma$માં ન આવતાં !!{constant}s હો. ઉલટાવી શકવાના ઉપપ્રમેયથી મળે છે:}
    \Gamma, \Gamma', R(c_1,\dots,c_n) & \Sequent  R'(c_1, \dots, c_n)
  \intertext{માએહારાનું ઉપપ્રમેય આના પર લગાવો:}
    \maeh{\Gamma, R(c_1,\dots,c_n)}{\Gamma'} & \Sequent
      \maeh{\ }{R'(c_1, \dots, c_n)}
  \intertext{ત્યારે એવું $!A \ident !A(x_1, \dots, x_n)$ મળે છે કે}
    \Gamma, R(c_1,\dots,c_n) & \Sequent !A(c_1, \dots, c_n) \\
    !A(c_1, \dots, c_n), \Gamma' & \Sequent R'(c_1, \dots, c_n)
  \intertext{આ બંનેની !!{proof}s છે. માએહારાના ઉપપ્રમેય મુજબ $\Lang L(!A) \subseteq \Lang L(\Gamma) \setminus \{R\}$; એટલે $!A$માં $R$ નથી. બીજા સિક્વન્ટની !!{proof}માં $R'$ને સર્વત્ર $R$થી બદલો; ત્યારે આની !!a{proof} મળે છે:}
    !A(c_1, \dots, c_n), \Gamma & \Sequent R(c_1, \dots, c_n)
  \end{align*}
  \sourcecorrection{OLMD-207}{મૂળમાં અંતર્વેશકની ભાષા સામાન્ય ભાષાના બરાબર છે અને અપરિભાષિત $L_1,L_2$ વાપરે છે; ઉપપ્રમેય માત્ર સમાવેશ આપે છે, જે અહીં પૂરતો છે.}
  બંને દિશાના અનુસરણો માટે
  \RightR{\lif}, પછી દ્વિમુખી
  સંબંધની રજૂઆત અને
  \RightR{\lforall} લગાવી
  આની !!a{proof} મેળવો:
  \sourcecorrection{OLMD-208}{મૂળમાં માત્ર અનુસરણ-જમણો અને સર્વમાન્યક-જમણો નિયમ લખેલા છે; બે દિશા ભેગી કરીને દ્વિમુખી સંબંધ બનાવવાનું મધ્યવર્તી પગલું પણ જરૂરી છે.}
  \[
    \Gamma \Sequent \lforall[x_1][\dots\lforall[x_n][(R(x_1,\dots,x_n) \liff !A(x_1, \dots, x_n))]].
  \]
  આ બતાવે છે કે
  $!A(x_1, \dots, x_n)$
  એ~$\Gamma$માં~$R$ને
  સ્પષ્ટ રીતે વ્યાખ્યાયિત કરે છે.
  \sourcecorrection{OLMD-209}{મૂળ અંતિમ વાક્યમાં $!R$ લખાયું છે, જ્યારે $R$ અહીં વ્યાખ્યાયિત થતું વિધેયચિહ્ન છે.}
\end{proof}

