source_text:
\begin{defn}
A rule~$R$ is \emph{admissible} in a sequent system if any sequent
that can be proved in that system together with the rule~$R$ can also
be proved without~$R$.
\end{defn}

target_text:
\begin{defn}
સિક્વન્ટ તંત્રમાં નિયમ~$R$ \emph{સ્વીકાર્ય} છે,
જો તંત્ર સાથે નિયમ~$R$ વાપરીને સાબિત થઈ શકે તે દરેક
સિક્વન્ટ~$R$ વિના પણ સાબિત થઈ શકે.
\end{defn}

source_text:
\begin{defn}
A rule~$R$,
\[
\AxiomC{$S_1$}
\AxiomC{$\dots$}
\AxiomC{$S_n$}
\RightLabel{$R$}
\TrinaryInfC{$S$}
\DisplayProof
\]
is called \emph{derivable} in a system if there is a schematic
!!{proof} of the sequent~$S$ using the rules and axioms of the system
together with additional initial sequents of the forms of~$S_1$, \dots,~$S_n$.
\end{defn}

target_text:
\begin{defn}
નિયમ~$R$,
\[
\AxiomC{$S_1$}
\AxiomC{$\dots$}
\AxiomC{$S_n$}
\RightLabel{$R$}
\TrinaryInfC{$S$}
\DisplayProof
\]
તંત્રમાં \emph{નિષ્પન્નક્ષમ} કહેવાય, જો તંત્રના નિયમો
અને સ્વયંસિદ્ધો સાથે~$S_1$, \dots,~$S_n$નાં સ્વરૂપના
વધારાના આરંભિક સિક્વન્ટો વાપરીને
સિક્વન્ટ~$S$ની ઢાંચારૂપ !!{proof} મળે.
\end{defn}

