\begin{defn}
A rule~$R$,
\[
\AxiomC{$S_1$}
\AxiomC{$\dots$}
\AxiomC{$S_n$}
\RightLabel{$R$}
\TrinaryInfC{$S$}
\DisplayProof
\]
is \emph{!!{height}-preserving admissible} (or
\emph{!!{hp}-admissible}) in a system if, whenever $\Proves[h_i] S_i$
for $i = 1$, \dots,~$n$, then $\Proves_m S$ with $m = \max(h_1, \dots,
h_n)$.
\end{defn}

target_text:
\begin{defn}
નિયમ~$R$,
\[
\AxiomC{$S_1$}
\AxiomC{$\dots$}
\AxiomC{$S_n$}
\RightLabel{$R$}
\TrinaryInfC{$S$}
\DisplayProof
\]
તંત્રમાં \emph{!!{height}-સંરક્ષક સ્વીકાર્ય}
(અથવા \emph{!!{hp}-સ્વીકાર્ય}) છે, જો
$\Proves[h_i] S_i$ એ $i = 1$, \dots,~$n$ માટે હોય,
ત્યારે $\Proves_m S$ હોય, જ્યાં $m = \max(h_1, \dots,
h_n)$.
\end{defn}

