\begin{cor}
If $\Gamma \Entails !A$ then $\Gamma \Proves !A$.
\end{cor}

target_text:
\begin{cor}
જો $\Gamma \Entails !A$ હોય, તો $\Gamma \Proves !A$.
\end{cor}

source_text:
\begin{proof}
If $\Gamma\Proves/ !A$ then $\Gamma \cup \{\lnot !A\}$ is consistent,
by \olref[axd]{prop:prov-incons}. So by the completeness theorem, $\Gamma \cup
\{\lnot !A\}$ is satisfiable, and $\Gamma \Entails/ !A$.
\end{proof}

\begin{prop}[Compactness Theorem]
\ollabel{prop:compactness}
$\Gamma$ is satisfiable if and only if every \emph{finite} subset
$\Gamma_0$ of $\Gamma$ is satisfiable.
\end{prop}

target_text:
\begin{prop}[સઘનતા પ્રમેય]
\ollabel{prop:compactness}
$\Gamma$ સંતોષ્ય છે જો અને ફક્ત જો $\Gamma$નો દરેક
\emph{સાંત} ઉપગણ~$\Gamma_0$ સંતોષ્ય હોય.
\end{prop}

source_text:
\begin{proof}
$\Gamma$ is unsatisfiable if and only if it is inconsistent, if and
  only if some finite subset $\Gamma_0$ of $\Gamma$ is inconsistent,
  if and only if some finite subset $\Gamma_0$ of $\Gamma$ is
  unsatisfiable.
\end{proof}

target_text:
\begin{proof}
$\Gamma$ અસંતોષ્ય છે જો અને ફક્ત જો તે અસુસંગત હોય;
જો અને ફક્ત જો $\Gamma$નો કોઈ સાંત ઉપગણ~$\Gamma_0$
અસુસંગત હોય; જો અને ફક્ત જો $\Gamma$નો કોઈ સાંત
ઉપગણ~$\Gamma_0$ અસંતોષ્ય હોય.
\end{proof}

source_text:
\begin{cor}
$\Gamma \Entails !A$ if and only if for some finite subset
$\Gamma_0$ of $\Gamma$, $\Gamma_0 \Entails !A$.
\end{cor}

target_text:
\begin{cor}
$\Gamma \Entails !A$ જો અને ફક્ત જો $\Gamma$ના
કોઈ સાંત ઉપગણ~$\Gamma_0$ માટે $\Gamma_0 \Entails !A$.
\end{cor}

source_text:
\begin{thm}[Soundness] 
\ollabel{thm:soundness} 
If $\Gamma\Proves!A$ then
$\Gamma \Entails !A$. 
\end{thm}

target_text:
\begin{thm}[યથાર્થતા]
\ollabel{thm:soundness}
જો $\Gamma\Proves!A$ હોય, તો $\Gamma \Entails !A$.
\end{thm}

